{
  "name": "StaffOptima - AI Workforce Planner",
  "description": "An interactive staffing optimization tool that ingests demand curves and productivity constraints to generate optimal associate rosters, shift mixes, and utilization insights using Gemini AI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Shift = 'Morning' | 'Evening' | 'Night';
export type DayOfWeek = 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat' | 'Sun';

export interface DemandData {
  day: DayOfWeek;
  morning: number;
  evening: number;
  night: number;
}

export interface Constraints {
  avgProductivity: number; // units per hour
  targetUtilization: number; // percentage (e.g., 0.85)
  maxGigPercentage: number; // percentage (e.g., 25)
  minWeeklyOffs: number; // e.g., 1 or 2
  weekendSpike: number; // percentage multiplier perception
}

// The structure received from Gemini
export interface StaffingSolution {
  strategySummary: string;
  weeklyStats: {
    totalVolume: number;
    totalHeadcount: number;
    blendedUtilization: number;
  };
  dailyPlan: {
    day: DayOfWeek;
    shifts: {
      shift: Shift;
      volume: number;
      requiredAssociates: number;
      allocated: {
        fullTime: number; // 8 hr
        partTime: number; // 4 hr
        gig: number; // Flexible
      };
      gap: number; // Over/Under staffing
    }[];
  }[];
  recommendations: string[];
}

export const INITIAL_DEMAND: DemandData[] = [
  { day: 'Mon', morning: 1200, evening: 1500, night: 800 },
  { day: 'Tue', morning: 1150, evening: 1400, night: 750 },
  { day: 'Wed', morning: 1200, evening: 1450, night: 800 },
  { day: 'Thu', morning: 1300, evening: 1600, night: 900 },
  { day: 'Fri', morning: 1600, evening: 2100, night: 1100 },
  { day: 'Sat', morning: 2200, evening: 2800, night: 1500 },
  { day: 'Sun', morning: 2000, evening: 2600, night: 1300 },
];

export const INITIAL_CONSTRAINTS: Constraints = {
  avgProductivity: 45, // items picked per hour per person
  targetUtilization: 85, // 85% utilization target
  maxGigPercentage: 25, // Max 25% gig workers
  minWeeklyOffs: 1,
  weekendSpike: 30, // Just a reference input
};

import { GoogleGenAI, Type } from "@google/genai";
import { Constraints, DemandData, StaffingSolution } from "../types";

const parseGeminiResponse = (text: string): StaffingSolution | null => {
  try {
    // Attempt to clean markdown if present
    const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    return null;
  }
};

export const generateStaffingPlan = async (
  demand: DemandData[],
  constraints: Constraints
): Promise<StaffingSolution> => {

  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a Senior Workforce Management (WFM) and Operations Research Expert.

    Task: Create an optimal bottom-up staffing roster based on the provided demand curve and constraints.

    Inputs:
    1. Demand Matrix (Volume in units): ${JSON.stringify(demand)}
    2. Operational Constraints:
       - Average Productivity: ${constraints.avgProductivity} units/associate/hour
       - Target Utilization: ${constraints.targetUtilization}%
       - Max Gig Worker Mix: ${constraints.maxGigPercentage}%
       - Mandatory Weekly Offs: Minimum ${constraints.minWeeklyOffs}
       - Shift Durations: Morning (8h), Evening (8h), Night (8h). Note: Demand is provided per shift total, not per hour, assume shift length is 8 hours for calculation of rate.

    Staff Profiles:
    - Full Time (FT): 8 hours, stable, lower attrition.
    - Part Time (PT): 4 hours, good for overlaps and peak management.
    - Gig: Flexible, used for extreme spikes (like Weekends), lower cost but higher variance.

    Goal:
    - Minimize "Lean Hours" (overstaffing).
    - Ensure coverage for "Weekend Spikes".
    - Respect the Max Gig % constraint.
    - Calculate 'Required Associates' = (Volume / (Productivity * 8)) / (Target Utilization / 100). *Adjust for shift length if using PT*.

    Output Requirements:
    Return a strict JSON object matching this schema. Do not include markdown code blocks, just raw JSON.

    Schema:
    {
      "strategySummary": "String explaining the approach (e.g. 'Heavy usage of PT on Sat evening to cover 30% spike...')",
      "weeklyStats": {
        "totalVolume": number,
        "totalHeadcount": number, // Sum of all shifts
        "blendedUtilization": number // Calculated average
      },
      "dailyPlan": [
        {
          "day": "Mon" | "Tue" | "Wed" | "Thu" | "Fri" | "Sat" | "Sun",
          "shifts": [
            {
              "shift": "Morning" | "Evening" | "Night",
              "volume": number,
              "requiredAssociates": number, // The mathematical raw need
              "allocated": {
                "fullTime": number,
                "partTime": number,
                "gig": number
              },
              "gap": number // (Total Allocated Capacity - Demand) positive means overstaffed, negative understaffed
            }
          ]
        }
      ],
      "recommendations": ["String", "String", "String"]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        temperature: 0.2, // Low temperature for mathematical consistency
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");

    const data = parseGeminiResponse(text);
    if (!data) throw new Error("Invalid JSON format received from AI");

    return data;

  } catch (error) {
    console.error("Gemini Optimization Error:", error);
    throw error;
  }
};

import React from 'react';
import { Constraints } from '../types';
import { Settings, Users, Activity, Percent } from 'lucide-react';

interface ConstraintsFormProps {
  constraints: Constraints;
  onChange: (c: Constraints) => void;
}

const ConstraintsForm: React.FC<ConstraintsFormProps> = ({ constraints, onChange }) => {
  const handleChange = (field: keyof Constraints, value: string) => {
    onChange({
      ...constraints,
      [field]: parseFloat(value) || 0,
    });
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
      <div className="flex items-center gap-2 mb-6">
        <Settings className="w-5 h-5 text-indigo-600" />
        <h2 className="text-lg font-semibold text-slate-800">Operational Constraints</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="flex items-center gap-2 text-sm font-medium text-slate-600 mb-2">
            <Activity className="w-4 h-4" />
            Productivity (Units/Hr)
          </label>
          <input
            type="number"
            value={constraints.avgProductivity}
            onChange={(e) => handleChange('avgProductivity', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
          />
          <p className="text-xs text-slate-400 mt-1">Expected throughput per associate</p>
        </div>

        <div>
          <label className="flex items-center gap-2 text-sm font-medium text-slate-600 mb-2">
            <Percent className="w-4 h-4" />
            Target Utilization (%)
          </label>
          <input
            type="number"
            value={constraints.targetUtilization}
            onChange={(e) => handleChange('targetUtilization', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
          />
          <p className="text-xs text-slate-400 mt-1">Optimal uptime target</p>
        </div>

        <div>
          <label className="flex items-center gap-2 text-sm font-medium text-slate-600 mb-2">
            <Users className="w-4 h-4" />
            Max Gig Mix (%)
          </label>
          <input
            type="number"
            value={constraints.maxGigPercentage}
            onChange={(e) => handleChange('maxGigPercentage', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
          />
          <p className="text-xs text-slate-400 mt-1">Cap on flexible workforce</p>
        </div>

         <div>
          <label className="flex items-center gap-2 text-sm font-medium text-slate-600 mb-2">
            <Activity className="w-4 h-4" />
            Weekend Spike Factor (%)
          </label>
          <input
            type="number"
            value={constraints.weekendSpike}
            onChange={(e) => handleChange('weekendSpike', e.target.value)}
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 transition-colors"
          />
          <p className="text-xs text-slate-400 mt-1">Estimated volume lift (Ref only)</p>
        </div>
      </div>
    </div>
  );
};

export default ConstraintsForm;

import React from 'react';
import { DemandData, DayOfWeek } from '../types';
import { BarChart3 } from 'lucide-react';

interface DemandInputProps {
  demand: DemandData[];
  onChange: (d: DemandData[]) => void;
}

const DemandInput: React.FC<DemandInputProps> = ({ demand, onChange }) => {
  const handleCellChange = (dayIndex: number, field: keyof DemandData, value: string) => {
    const numValue = parseInt(value) || 0;
    const newDemand = [...demand];
    newDemand[dayIndex] = { ...newDemand[dayIndex], [field]: numValue };
    onChange(newDemand);
  };

  const calculateDailyTotal = (d: DemandData) => d.morning + d.evening + d.night;

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="flex items-center gap-2 mb-6">
        <BarChart3 className="w-5 h-5 text-indigo-600" />
        <h2 className="text-lg font-semibold text-slate-800">Demand Curve Input</h2>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="bg-slate-50 text-slate-600 font-medium">
            <tr>
              <th className="px-4 py-3 rounded-l-lg">Day</th>
              <th className="px-4 py-3">Morning</th>
              <th className="px-4 py-3">Evening</th>
              <th className="px-4 py-3">Night</th>
              <th className="px-4 py-3 rounded-r-lg text-right">Total Volume</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {demand.map((dayData, index) => (
              <tr key={dayData.day} className="hover:bg-slate-50 transition-colors">
                <td className="px-4 py-3 font-medium text-slate-700">{dayData.day}</td>
                <td className="px-4 py-3">
                  <input
                    type="number"
                    className="w-24 px-2 py-1 border border-slate-200 rounded focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    value={dayData.morning}
                    onChange={(e) => handleCellChange(index, 'morning', e.target.value)}
                  />
                </td>
                <td className="px-4 py-3">
                  <input
                    type="number"
                    className="w-24 px-2 py-1 border border-slate-200 rounded focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    value={dayData.evening}
                    onChange={(e) => handleCellChange(index, 'evening', e.target.value)}
                  />
                </td>
                <td className="px-4 py-3">
                  <input
                    type="number"
                    className="w-24 px-2 py-1 border border-slate-200 rounded focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    value={dayData.night}
                    onChange={(e) => handleCellChange(index, 'night', e.target.value)}
                  />
                </td>
                <td className="px-4 py-3 text-right font-semibold text-indigo-600">
                  {calculateDailyTotal(dayData).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="mt-4 text-xs text-slate-400 italic">
        * Inputs are in Volume Units (e.g., Orders, Items)
      </div>
    </div>
  );
};

export default DemandInput;

import React, { useState } from 'react';
import { INITIAL_CONSTRAINTS, INITIAL_DEMAND, Constraints, DemandData, StaffingSolution } from './types';
import DemandInput from './components/DemandInput';
import ConstraintsForm from './components/ConstraintsForm';
import SolutionDashboard from './components/SolutionDashboard';
import { generateStaffingPlan } from './services/geminiService';
import { Layers, Zap, Loader2, LayoutDashboard, Calculator } from 'lucide-react';

export default function App() {
  const [activeTab, setActiveTab] = useState<'input' | 'results'>('input');
  const [demand, setDemand] = useState<DemandData[]>(INITIAL_DEMAND);
  const [constraints, setConstraints] = useState<Constraints>(INITIAL_CONSTRAINTS);
  const [isLoading, setIsLoading] = useState(false);
  const [solution, setSolution] = useState<StaffingSolution | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleOptimize = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await generateStaffingPlan(demand, constraints);
      setSolution(result);
      setActiveTab('results');
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred during optimization.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-600 rounded-lg">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">StaffOptima</h1>
          </div>
          <nav className="flex items-center gap-1 bg-slate-100 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('input')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${
                activeTab === 'input' 
                  ? 'bg-white text-indigo-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Model Inputs
            </button>
            <button
              onClick={() => solution && setActiveTab('results')}
              disabled={!solution}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${
                activeTab === 'results' 
                  ? 'bg-white text-indigo-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700 disabled:opacity-50'
              }`}
            >
              Results
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
            <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-red-500"></div>
                {error}
            </div>
        )}

        {activeTab === 'input' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-4 duration-500">
            {/* Left Column: Inputs */}
            <div className="lg:col-span-2 space-y-6">
              <DemandInput demand={demand} onChange={setDemand} />
            </div>

            {/* Right Column: Constraints & Action */}
            <div className="space-y-6">
              <ConstraintsForm constraints={constraints} onChange={setConstraints} />

              <div className="bg-slate-800 text-white p-6 rounded-xl shadow-lg">
                <h3 className="text-lg font-semibold mb-2 flex items-center gap-2">
                  <Zap className="w-5 h-5 text-yellow-400" />
                  Ready to Optimize?
                </h3>
                <p className="text-slate-300 text-sm mb-6">
                  Our AI model will analyze your demand curve against productivity constraints to maximize utilization and reduce lean hours.
                </p>
                <button
                  onClick={handleOptimize}
                  disabled={isLoading}
                  className="w-full bg-indigo-500 hover:bg-indigo-400 text-white font-semibold py-3 px-4 rounded-lg transition-colors flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      Optimizing Roster...
                    </>
                  ) : (
                    <>
                      <Calculator className="w-5 h-5" />
                      Generate Optimal Roster
                    </>
                  )}
                </button>
              </div>

               {/* Hint Box */}
               <div className="bg-blue-50 border border-blue-100 p-4 rounded-lg text-sm text-blue-800">
                <strong>Tip:</strong> Ensure you have set your <code className="bg-white px-1 py-0.5 rounded border border-blue-200">API_KEY</code> in the environment variables to use the Gemini optimization engine.
              </div>
            </div>
          </div>
        )}

        {activeTab === 'results' && solution && (
          <SolutionDashboard solution={solution} />
        )}
      </main>
    </div>
  );
}

export type TimeBlock = 
  | '06:00-10:00' 
  | '10:00-14:00' 
  | '14:00-18:00' 
  | '18:00-22:00' 
  | '22:00-02:00' 
  | '02:00-06:00';

export type DayOfWeek = 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat' | 'Sun';
export type RoleType = 'Full Time' | 'Part Time' | 'Weekend Warrior';

export interface DemandData {
  day: DayOfWeek;
  // Dynamic map for the 6 blocks
  blocks: Record<TimeBlock, number>;
}

export interface Constraints {
  avgProductivity: number; // units per hour
  targetUtilization: number; // percentage (e.g., 0.85)
  minWeeklyOffs: number; // e.g., 1 or 2
  weekendSpike: number; // percentage multiplier perception (informational)
}

export interface AssociateRoster {
  id: string;
  name: string;
  role: RoleType;
  schedule: Record<DayOfWeek, string>; // e.g., "06:00 - 15:00" or "OFF"
  totalHours: number;
}

// The structure received from Gemini
export interface StaffingSolution {
  strategySummary: string;
  weeklyStats: {
    totalVolume: number;
    totalHeadcount: number;
    blendedUtilization: number;
    mix: {
      ft: number;
      pt: number;
      weekend: number;
    };
  };
  roster: AssociateRoster[];
  recommendations: string[];
}

// Initial data helper
const createEmptyDay = (day: DayOfWeek): DemandData => ({
  day,
  blocks: {
    '06:00-10:00': 0,
    '10:00-14:00': 0,
    '14:00-18:00': 0,
    '18:00-22:00': 0,
    '22:00-02:00': 0,
    '02:00-06:00': 0,
  }
});

export const INITIAL_DEMAND: DemandData[] = [
  { ...createEmptyDay('Mon'), blocks: { '06:00-10:00': 500, '10:00-14:00': 800, '14:00-18:00': 700, '18:00-22:00': 600, '22:00-02:00': 200, '02:00-06:00': 100 }},
  createEmptyDay('Tue'),
  createEmptyDay('Wed'),
  createEmptyDay('Thu'),
  createEmptyDay('Fri'),
  createEmptyDay('Sat'),
  createEmptyDay('Sun'),
];

export const INITIAL_CONSTRAINTS: Constraints = {
  avgProductivity: 45, // items picked per hour per person
  targetUtilization: 85, // 85% utilization target
  minWeeklyOffs: 1,
  weekendSpike: 30, 
};

export const TIME_BLOCKS: TimeBlock[] = [
  '06:00-10:00', 
  '10:00-14:00', 
  '14:00-18:00', 
  '18:00-22:00', 
  '22:00-02:00', 
  '02:00-06:00'
];

import React from 'react';
import { DemandData, TIME_BLOCKS, DayOfWeek, TimeBlock } from '../types';
import { BarChart3, Copy } from 'lucide-react';

interface DemandInputProps {
  demand: DemandData[];
  onChange: (d: DemandData[]) => void;
}

const DemandInput: React.FC<DemandInputProps> = ({ demand, onChange }) => {
  const handleCellChange = (dayIndex: number, block: TimeBlock, value: string) => {
    const numValue = parseInt(value) || 0;
    const newDemand = [...demand];
    newDemand[dayIndex] = {
      ...newDemand[dayIndex],
      blocks: {
        ...newDemand[dayIndex].blocks,
        [block]: numValue
      }
    };
    onChange(newDemand);
  };

  const copyMondayToAll = () => {
    const mondayData = demand[0].blocks;
    const newDemand = demand.map((d, i) => {
      if (i === 0) return d; // Skip monday
      return {
        ...d,
        blocks: { ...mondayData }
      };
    });
    onChange(newDemand);
  };

  const calculateDailyTotal = (d: DemandData) => {
    return Object.values(d.blocks).reduce((sum, val) => sum + val, 0);
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-2">
          <BarChart3 className="w-5 h-5 text-indigo-600" />
          <h2 className="text-lg font-semibold text-slate-800">24/7 Demand Input (4hr Blocks)</h2>
        </div>
        <button 
          onClick={copyMondayToAll}
          className="text-xs flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-md transition-colors font-medium"
        >
          <Copy className="w-3 h-3" />
          Copy Mon to All
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-xs text-left">
          <thead className="bg-slate-50 text-slate-600 font-medium border-b border-slate-200">
            <tr>
              <th className="px-3 py-3 w-20 sticky left-0 bg-slate-50 z-10">Day</th>
              {TIME_BLOCKS.map(block => (
                <th key={block} className="px-2 py-3 text-center whitespace-nowrap min-w-[80px]">
                  {block}
                </th>
              ))}
              <th className="px-3 py-3 text-right sticky right-0 bg-slate-50 z-10">Total</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {demand.map((dayData, index) => (
              <tr key={dayData.day} className="hover:bg-slate-50 transition-colors group">
                <td className="px-3 py-2 font-medium text-slate-700 sticky left-0 bg-white group-hover:bg-slate-50 z-10">
                  {dayData.day}
                </td>
                {TIME_BLOCKS.map(block => (
                  <td key={block} className="px-2 py-2">
                    <input
                      type="number"
                      className="w-full px-2 py-1.5 text-center border border-slate-200 rounded focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all text-slate-600"
                      value={dayData.blocks[block] || ''}
                      placeholder="0"
                      onChange={(e) => handleCellChange(index, block, e.target.value)}
                    />
                  </td>
                ))}
                <td className="px-3 py-2 text-right font-semibold text-indigo-600 sticky right-0 bg-white group-hover:bg-slate-50 z-10">
                  {calculateDailyTotal(dayData).toLocaleString()}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="mt-4 text-xs text-slate-400 italic flex justify-between">
        <span>* Inputs are in Volume Units (e.g., Orders) for each 4-hour window.</span>
        <span>Starts at 6:00 AM daily.</span>
      </div>
    </div>
  );
};

export default DemandInput;

import { GoogleGenAI } from "@google/genai";
import { Constraints, DemandData, StaffingSolution } from "../types";

const parseGeminiResponse = (text: string): StaffingSolution | null => {
  try {
    const cleaned = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {
    console.error("Failed to parse Gemini response", e);
    return null;
  }
};

export const generateStaffingPlan = async (
  demand: DemandData[],
  constraints: Constraints
): Promise<StaffingSolution> => {

  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Serialize demand for prompt
  const demandSummary = demand.map(d => `${d.day}: ${JSON.stringify(d.blocks)}`).join('\n');

  const prompt = `
    You are an expert Workforce Manager.

    Task: Create a detailed Staffing Roster (list of specific associates) to cover the following 24/7 demand curve.

    INPUT DATA (Volume per 4-hour block):
    ${demandSummary}

    OPERATIONAL PARAMETERS:
    - Productivity: ${constraints.avgProductivity} units/hour/person.
    - Target Utilization: ${constraints.targetUtilization}%.
    - Mandatory Offs: At least ${constraints.minWeeklyOffs} day(s) off per week per person.

    SHIFT DEFINITIONS:
    1. Full Time (FT):
       - Duration: 9 hours total span.
       - Composition: 8 working hours + 1 hour unpaid break (typically in the middle).
       - Examples: 06:00-15:00, 14:00-23:00.
    2. Part Time (PT):
       - Duration: 4 hours continuous work.
       - No break.
       - Great for covering peaks (e.g., 18:00-22:00).
    3. Weekend Warriors:
       - Can be FT or PT, but scheduled primarily on Sat/Sun.

    OPTIMIZATION GOALS:
    1. Calculate required headcount per block = (Volume / Productivity) / Utilization.
    2. Assign specific Shifts to individual "Associates" to meet this requirement.
    3. Minimize lean hours (overstaffing).
    4. Ensure every associate has at least ${constraints.minWeeklyOffs} day off.
    5. Prioritize Full Time for base load, Part Time for peaks.

    OUTPUT SCHEMA (JSON Only):
    {
      "strategySummary": "Explanation of the mix (e.g. 'Used 10 FT for base load, 5 PT for evening peaks...')",
      "weeklyStats": {
        "totalVolume": number,
        "totalHeadcount": number, // Total unique people
        "blendedUtilization": number,
        "mix": { "ft": number, "pt": number, "weekend": number } // Counts of each type
      },
      "roster": [
        {
          "id": "101",
          "name": "Associate 1",
          "role": "Full Time" | "Part Time" | "Weekend Warrior",
          "schedule": {
            "Mon": "06:00-15:00",
            "Tue": "06:00-15:00",
            "Wed": "OFF",
            "Thu": "06:00-15:00",
            "Fri": "06:00-15:00",
            "Sat": "06:00-15:00",
            "Sun": "OFF"
          },
          "totalHours": number
        }
        ... generate as many as needed to cover demand
      ],
      "recommendations": ["Tip 1", "Tip 2"]
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        temperature: 0.2, 
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");

    const data = parseGeminiResponse(text);
    if (!data) throw new Error("Invalid JSON format received from AI");

    return data;

  } catch (error) {
    console.error("Gemini Optimization Error:", error);
    throw error;
  }
};

