import { AssociateRoster, Constraints, DemandData, StaffingSolution, TIME_BLOCKS, DayOfWeek, TimeBlock } from "../types";

// Helper to map block index to time string
const getBlockLabel = (index: number): TimeBlock => TIME_BLOCKS[index];

// Helper to generate a consistent ID
const generateId = () => Math.random().toString(36).substr(2, 9);

interface ShiftRequirement {
  id: string;
  day: DayOfWeek;
  dayIndex: number;
  blockIndex: number; // Starting block index
  type: 'FT' | 'PT';
  durationHours: number; // 8 for FT (net), 4 for PT
}

export const generateAlgorithmicStaffingPlan = (
  demandData: DemandData[],
  constraints: Constraints
): StaffingSolution => {

  const dailyShiftsNeeded: ShiftRequirement[] = [];
  const debugLog: string[] = [];

  // --- Step 1: Calculate Required Headcount & Decompose into Shifts ---

  demandData.forEach((dayData, dayIdx) => {
    // 1. Convert Volume to Headcount
    // Formula: Volume / (Prod/hr * 4hr block * Utilization)
    const blockCapacities = TIME_BLOCKS.map(block => {
      const vol = dayData.blocks[block];
      // Capacity of 1 person for 4 hours adjusted by utilization target
      const onePersonCapacity = constraints.avgProductivity * 4 * (constraints.targetUtilization / 100);
      return Math.ceil(vol / onePersonCapacity); // Round up to ensure coverage
    });

    // 2. Greedy Shift Assignment
    // Strategy: Find overlap between adjacent blocks to maximize Full Time usage.
    // We treat block array as mutable to subtract coverage as we assign shifts.
    const uncovered = [...blockCapacities];

    // Try to fit FT shifts (2 consecutive blocks)
    // We iterate through possible start times. 
    // Optimization: Prioritize starts that align with traditional shifts (0->Morning, 2->Evening, 4->Night)
    // But allow flexibility to minimize gaps.

    // Pass 1: Full Time Assignment
    for (let i = 0; i < TIME_BLOCKS.length; i++) {
      // Look ahead for 2-block overlap
      // Note: This logic assumes 24h cycle but simplified to daily cut-off for this version.
      // To support wrapping (Night shift covering next day morning), we'd need a continuous timeline.
      // For now, we assume shifts start and effective hours fall within the 'day' definition or logical 24h blocks.

      const currentBlock = i;
      const nextBlock = (i + 1) % TIME_BLOCKS.length; // Wrap around for night shifts

      // If wrapping to next day, we handle it simply by looking at current day's numbers for planning
      // Real WFM systems link Day N and Day N+1. Here we optimize Day N pattern.

      if (i < TIME_BLOCKS.length - 1) {
        // Simple pair within the day
        while (uncovered[currentBlock] > 0 && uncovered[nextBlock] > 0) {
          // Found a slot where both blocks need people. Assign FT.
          dailyShiftsNeeded.push({
            id: generateId(),
            day: dayData.day,
            dayIndex: dayIdx,
            blockIndex: currentBlock,
            type: 'FT',
            durationHours: 8, // Net working hours assumption for calculation
          });
          uncovered[currentBlock]--;
          uncovered[nextBlock]--;
        }
      }
    }

    // Pass 2: Fill remaining gaps with Part Time
    for (let i = 0; i < TIME_BLOCKS.length; i++) {
      while (uncovered[i] > 0) {
        dailyShiftsNeeded.push({
          id: generateId(),
          day: dayData.day,
          dayIndex: dayIdx,
          blockIndex: i,
          type: 'PT',
          durationHours: 4,
        });
        uncovered[i]--;
      }
    }
  });

  // --- Step 2: Assign Shifts to Associates (Rostering) ---

  const associates: AssociateRoster[] = [];
  const maxDaysWork = 7 - constraints.minWeeklyOffs;

  // Sort shifts to prioritize consistency:
  // Group by Type (FT first), then by Start Time, then by Day.
  // This helps us give the same associate the same shift time across the week.
  dailyShiftsNeeded.sort((a, b) => {
    if (a.type !== b.type) return a.type === 'FT' ? -1 : 1;
    if (a.blockIndex !== b.blockIndex) return a.blockIndex - b.blockIndex;
    return a.dayIndex - b.dayIndex;
  });

  // Track unassigned shifts
  const unassignedShifts = [...dailyShiftsNeeded];

  let safetyCounter = 0;
  while (unassignedShifts.length > 0 && safetyCounter < 5000) {
    safetyCounter++;

    // Grab the first available shift to start a new Associate's schedule
    const seedShift = unassignedShifts.shift()!;

    const newAssociate: AssociateRoster = {
      id: generateId(),
      name: `Associate ${associates.length + 1}`,
      role: seedShift.type === 'FT' ? 'Full Time' : 'Part Time',
      schedule: { Mon: 'OFF', Tue: 'OFF', Wed: 'OFF', Thu: 'OFF', Fri: 'OFF', Sat: 'OFF', Sun: 'OFF' },
      totalHours: 0
    };

    // Assign the seed shift
    newAssociate.schedule[seedShift.day] = formatShiftTime(seedShift.blockIndex, seedShift.type);
    newAssociate.totalHours += seedShift.durationHours;

    let daysWorked = 1;
    const daysBusy = new Set<string>();
    daysBusy.add(seedShift.day);

    // Try to fill their week with similar shifts
    // Look for shifts of the SAME TYPE and SAME START TIME on OTHER days
    for (let d = 0; d < 7; d++) {
      if (daysWorked >= maxDaysWork) break;

      const currentDay = demandData[d].day;
      if (daysBusy.has(currentDay)) continue;

      // Find best match in unassigned pool
      const matchIndex = unassignedShifts.findIndex(s => 
        s.day === currentDay && 
        s.type === seedShift.type && 
        s.blockIndex === seedShift.blockIndex
      );

      if (matchIndex !== -1) {
        const match = unassignedShifts.splice(matchIndex, 1)[0];
        newAssociate.schedule[match.day] = formatShiftTime(match.blockIndex, match.type);
        newAssociate.totalHours += match.durationHours;
        daysBusy.add(match.day);
        daysWorked++;
      }
    }

    // Tag Weekend Warriors if they only work Sat/Sun
    const workedDays = Object.keys(newAssociate.schedule).filter(k => newAssociate.schedule[k as DayOfWeek] !== 'OFF');
    const isWeekendOnly = workedDays.every(d => d === 'Sat' || d === 'Sun');
    if (isWeekendOnly) newAssociate.role = 'Weekend Warrior';

    associates.push(newAssociate);
  }

  // --- Step 3: Stats & Summary ---

  const totalVolume = demandData.reduce((sum, d) => sum + Object.values(d.blocks).reduce((a, b) => a + b, 0), 0);
  const totalHours = associates.reduce((sum, a) => sum + a.totalHours, 0);

  // Back-calculate utilization based on capacity provided vs needed
  // Capacity Provided = Total Hours * Avg Productivity
  // This is a rough heuristic for the dashboard
  const capacityProvided = totalHours * constraints.avgProductivity;
  // If capacity provided < total volume, util is > 100% (understaffed). 
  // If capacity provided > total volume, util is < 100% (overstaffed).
  // Standard Util % = (Work / Paid Time) -> (Volume / Productivity) / TotalHours
  const calculatedUtilization = totalHours > 0 
    ? ((totalVolume / constraints.avgProductivity) / totalHours) * 100 
    : 0;

  const ftCount = associates.filter(a => a.role === 'Full Time').length;
  const ptCount = associates.filter(a => a.role === 'Part Time').length;
  const wkCount = associates.filter(a => a.role === 'Weekend Warrior').length;

  const summary = `Generated a roster with ${ftCount} Full-Time, ${ptCount} Part-Time, and ${wkCount} Weekend associates. ` +
    `The algorithm prioritized Full-Time shifts for base load and Part-Time for peaks to minimize lean hours. ` +
    `Blended utilization is ${calculatedUtilization.toFixed(1)}%.`;

  return {
    strategySummary: summary,
    weeklyStats: {
      totalVolume,
      totalHeadcount: associates.length,
      blendedUtilization: Math.min(calculatedUtilization, 100), // Cap visual at 100 usually
      mix: {
        ft: ftCount,
        pt: ptCount,
        weekend: wkCount
      }
    },
    roster: associates,
    recommendations: [
      "Review 'Weekend Warrior' shifts to ensure availability.",
      "Check specific days with high Part-Time usage for potential hiring needs.",
      "Full-Time shifts are assumed to span 2 blocks (8 hours work). Ensure break times are scheduled between blocks."
    ]
  };
};

// Helper: Convert block index to human readable shift time
// Block 0: 06:00, Block 1: 10:00...
const formatShiftTime = (startIndex: number, type: 'FT' | 'PT'): string => {
  const startHour = 6 + (startIndex * 4);
  const duration = type === 'FT' ? 9 : 4; // FT is 9h span (1h break), PT is 4h

  const endHour = (startHour + duration) % 24;

  const format = (h: number) => `${h.toString().padStart(2, '0')}:00`;

  // Handle crossing midnight for display
  const startStr = format(startHour >= 24 ? startHour - 24 : startHour);
  const endStr = format(endHour);

  return `${startStr}-${endStr}`;
};

import React, { useState } from 'react';
