import { AssociateRoster, Constraints, DemandData, StaffingSolution, TIME_BLOCKS, DayOfWeek, TimeBlock } from "../types";

// Helper to map block index to time string
const getBlockLabel = (index: number): TimeBlock => TIME_BLOCKS[index];

// Helper to generate a consistent ID
const generateId = () => Math.random().toString(36).substr(2, 9);

interface ShiftRequirement {
  id: string;
  day: DayOfWeek;
  dayIndex: number;
  blockIndex: number; // Starting block index
  type: 'FT' | 'PT';
  durationHours: number; // 8 for FT (net), 4 for PT
}

export const generateAlgorithmicStaffingPlan = (
  demandData: DemandData[],
  constraints: Constraints
): StaffingSolution => {

  const dailyShiftsNeeded: ShiftRequirement[] = [];

  // --- Step 1: Calculate Required Headcount & Decompose into Shifts ---

  demandData.forEach((dayData, dayIdx) => {
    // 1. Convert Volume to Headcount
    // Formula: Volume / (Prod/hr * 4hr block * Utilization)
    const blockCapacities = TIME_BLOCKS.map(block => {
      const vol = dayData.blocks[block];
      // Capacity of 1 person for 4 hours adjusted by utilization target
      const onePersonCapacity = constraints.avgProductivity * 4 * (constraints.targetUtilization / 100);
      return Math.ceil(vol / onePersonCapacity); // Round up to ensure coverage
    });

    // 2. Greedy Shift Assignment
    const uncovered = [...blockCapacities];

    // Pass 1: Full Time Assignment (2 blocks)
    for (let i = 0; i < TIME_BLOCKS.length; i++) {
      const currentBlock = i;
      const nextBlock = (i + 1) % TIME_BLOCKS.length; // Wrap around for night shifts

      if (i < TIME_BLOCKS.length - 1) {
        // Simple pair within the day
        while (uncovered[currentBlock] > 0 && uncovered[nextBlock] > 0) {
          dailyShiftsNeeded.push({
            id: generateId(),
            day: dayData.day,
            dayIndex: dayIdx,
            blockIndex: currentBlock,
            type: 'FT',
            durationHours: 8, 
          });
          uncovered[currentBlock]--;
          uncovered[nextBlock]--;
        }
      }
    }

    // Pass 2: Part Time (remaining blocks)
    for (let i = 0; i < TIME_BLOCKS.length; i++) {
      while (uncovered[i] > 0) {
        dailyShiftsNeeded.push({
          id: generateId(),
          day: dayData.day,
          dayIndex: dayIdx,
          blockIndex: i,
          type: 'PT',
          durationHours: 4,
        });
        uncovered[i]--;
      }
    }
  });

  // --- Step 2: Assign Shifts to Associates (Rostering) ---

  const associates: AssociateRoster[] = [];
  // LEGAL REQUIREMENT: 1 Day off minimum -> Max 6 days work.
  // The algorithm attempts to fill 6 days for everyone.
  const maxDaysWork = 6; 

  // Sort unassigned shifts to prioritize consistency:
  dailyShiftsNeeded.sort((a, b) => {
    if (a.type !== b.type) return a.type === 'FT' ? -1 : 1;
    if (a.blockIndex !== b.blockIndex) return a.blockIndex - b.blockIndex;
    return a.dayIndex - b.dayIndex;
  });

  const unassignedShifts = [...dailyShiftsNeeded];

  let safetyCounter = 0;
  while (unassignedShifts.length > 0 && safetyCounter < 10000) {
    safetyCounter++;

    // Create new associate with a seed shift
    const seedShift = unassignedShifts.shift()!;

    const newAssociate: AssociateRoster = {
      id: generateId(),
      name: `Temp Name`, // Will be renamed later
      role: seedShift.type === 'FT' ? 'Full Time' : 'Part Time',
      schedule: { Mon: 'OFF', Tue: 'OFF', Wed: 'OFF', Thu: 'OFF', Fri: 'OFF', Sat: 'OFF', Sun: 'OFF' },
      totalHours: 0
    };

    // Helper to assign
    const assignShift = (shift: ShiftRequirement) => {
      newAssociate.schedule[shift.day] = formatShiftTime(shift.blockIndex, shift.type);
      newAssociate.totalHours += shift.durationHours;
      daysBusy.add(shift.day);
      daysWorked++;
    };

    let daysWorked = 0;
    const daysBusy = new Set<string>();
    assignShift(seedShift);

    // SPECIAL WEEKEND LOGIC:
    // If seed is Sat, try to find Sun. If seed is Sun, try to find Sat.
    // This helps satisfy "Work at least 2 weekends" (interpreted as both Sat/Sun)
    if (seedShift.day === 'Sat' || seedShift.day === 'Sun') {
      const targetDay = seedShift.day === 'Sat' ? 'Sun' : 'Sat';
      const weekendMatchIdx = unassignedShifts.findIndex(s => 
        s.day === targetDay && 
        s.type === seedShift.type && 
        s.blockIndex === seedShift.blockIndex
      );

      if (weekendMatchIdx !== -1) {
        assignShift(unassignedShifts.splice(weekendMatchIdx, 1)[0]);
      }
    }

    // GENERAL FILL LOGIC:
    // Try to fill remaining days up to maxDaysWork (6)
    // We iterate through all days of the week to find matching shifts.
    for (let d = 0; d < 7; d++) {
      if (daysWorked >= maxDaysWork) break;

      const currentDay = demandData[d].day;
      if (daysBusy.has(currentDay)) continue;

      // Find best match: Same Type, Same Start Time
      const matchIndex = unassignedShifts.findIndex(s => 
        s.day === currentDay && 
        s.type === seedShift.type && 
        s.blockIndex === seedShift.blockIndex
      );

      if (matchIndex !== -1) {
        assignShift(unassignedShifts.splice(matchIndex, 1)[0]);
      } else {
        // Loose match: Same Type, adjacent start time (+/- 1 block)
        // Useful if perfect match not available, but prefer perfect consistency first
        // Adding this would increase utilization but might create irregular shifts.
        // Keeping strict start time consistency for now as it's better for employees.
      }
    }

    // Tag Weekend Warriors:
    // Definition: Works Sat AND Sun, and maybe fewer other days? 
    // Or just strictly works weekends. 
    // Prompt: "Every weekend worker will work at least 2 weekends".
    // We verify if they work both Sat and Sun.
    const worksSat = newAssociate.schedule['Sat'] !== 'OFF';
    const worksSun = newAssociate.schedule['Sun'] !== 'OFF';
    const totalDays = Object.values(newAssociate.schedule).filter(v => v !== 'OFF').length;

    // If they work ONLY weekends, or primarily weekends with low days, tag them.
    // Or if they are explicitly covering the weekend spike.
    if (worksSat && worksSun && totalDays <= 3) {
      newAssociate.role = 'Weekend Warrior';
    }

    associates.push(newAssociate);
  }

  // --- Step 3: Sort & Rename ---
  const rolePriority: Record<string, number> = { 
    'Full Time': 1, 
    'Weekend Warrior': 2, 
    'Part Time': 3 
  };

  associates.sort((a, b) => {
    // Primary Sort: Role
    const roleDiff = (rolePriority[a.role] || 99) - (rolePriority[b.role] || 99);
    if (roleDiff !== 0) return roleDiff;

    // Secondary Sort: Total Hours (descending)
    return b.totalHours - a.totalHours;
  });

  // Re-assign names sequentially after sorting
  associates.forEach((associate, index) => {
    associate.name = `Associate ${index + 1}`;
  });

  // --- Step 4: Stats ---
  const totalVolume = demandData.reduce((sum, d) => sum + Object.values(d.blocks).reduce((a, b) => a + b, 0), 0);
  const totalHours = associates.reduce((sum, a) => sum + a.totalHours, 0);

  const calculatedUtilization = totalHours > 0 
    ? ((totalVolume / constraints.avgProductivity) / totalHours) * 100 
    : 0;

  const ftCount = associates.filter(a => a.role === 'Full Time').length;
  const ptCount = associates.filter(a => a.role === 'Part Time').length;
  const wkCount = associates.filter(a => a.role === 'Weekend Warrior').length;

  const summary = `
    **Optimization Algorithm Methodology:**
    This roster was generated using a **Greedy Constructive Heuristic** with strict constraint satisfaction.

    1.  **Demand Deconstruction:** Demand is converted to headcount based on ${constraints.avgProductivity} UPH and ${constraints.targetUtilization}% utilization.
    2.  **Shift Tessellation:** Base volume is covered by 9-hour Full-Time shifts. Peaks are shaved using 4-hour Part-Time blocks.
    3.  **Associate Rostering (Bin Packing):**
        *   **Full-Time Logic:** Prioritized to work **6 days a week** (1 day off), ensuring maximum earning potential and stability.
        *   **Weekend Logic:** The algorithm explicitly pairs Saturday and Sunday shifts to ensure weekend continuity. Associates working primarily weekends are tagged as **Weekend Warriors**.
        *   **Part-Time Logic:** Also optimized for a 6-day work week where possible to maximize individual utility.

    **Outcome:**
    Generated a sorted roster with **${ftCount} Full-Time**, **${wkCount} Weekend Warriors**, and **${ptCount} Part-Time** associates. Names have been ordered by role for clarity.
  `.trim();

  return {
    strategySummary: summary,
    weeklyStats: {
      totalVolume,
      totalHeadcount: associates.length,
      blendedUtilization: Math.min(calculatedUtilization, 100), 
      mix: {
        ft: ftCount,
        pt: ptCount,
        weekend: wkCount
      }
    },
    roster: associates,
    recommendations: [
      "Weekend Warriors are scheduled for both Sat & Sun to meet the '2 weekend' constraint.",
      "Full Time and Part Time staff are optimized for a 6-day work week (1 weekly off).",
      "Breaks (1hr) are assumed for all Full Time shifts (8hrs work + 1hr break)."
    ]
  };
};

// Helper: Convert block index to human readable shift time
const formatShiftTime = (startIndex: number, type: 'FT' | 'PT'): string => {
  const startHour = 6 + (startIndex * 4);
  const duration = type === 'FT' ? 9 : 4; // FT is 9h span (1h break), PT is 4h

  const endHour = (startHour + duration) % 24;

  const format = (h: number) => `${h.toString().padStart(2, '0')}:00`;

  // Handle crossing midnight for display
  const startStr = format(startHour >= 24 ? startHour - 24 : startHour);
  const endStr = format(endHour);

  return `${startStr}-${endStr}`;
};

export type TimeBlock = 
  | '06:00-10:00' 
  | '10:00-14:00' 
  | '14:00-18:00' 
  | '18:00-22:00' 
  | '22:00-02:00' 
  | '02:00-06:00';

export type DayOfWeek = 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat' | 'Sun';
export type RoleType = 'Full Time' | 'Part Time' | 'Weekend Warrior';

export interface DemandData {
  day: DayOfWeek;
  // Dynamic map for the 6 blocks
  blocks: Record<TimeBlock, number>;
}

export interface Constraints {
  avgProductivity: number; // units per hour
  targetUtilization: number; // percentage (e.g., 0.85)
  minWeeklyOffs: number; // e.g., 1 or 2
  weekendSpike: number; // percentage multiplier perception (informational)
}

export interface AssociateRoster {
  id: string;
  name: string;
  role: RoleType;
  schedule: Record<DayOfWeek, string>; // e.g., "06:00 - 15:00" or "OFF"
  totalHours: number;
}

// The structure received from Gemini
export interface StaffingSolution {
  strategySummary: string;
  weeklyStats: {
    totalVolume: number;
    totalHeadcount: number;
    blendedUtilization: number;
    mix: {
      ft: number;
      pt: number;
      weekend: number;
    };
  };
  roster: AssociateRoster[];
  recommendations: string[];
}

