import { AssociateRoster, Constraints, DemandData, StaffingSolution, TIME_BLOCKS, DayOfWeek, TimeBlock } from "../types";

// Helper to generate a consistent ID
const generateId = () => Math.random().toString(36).substr(2, 9);

interface ShiftUnit {
  day: DayOfWeek;
  dayIndex: number; // 0=Mon, 6=Sun
  blockIndex: number;
  type: 'FT' | 'PT'; // FT = 8h (2 blocks), PT = 4h (1 block)
  durationHours: number;
}

export const generateAlgorithmicStaffingPlan = (
  demandData: DemandData[],
  constraints: Constraints
): StaffingSolution => {

  // --- Step 1: Deconstruct Demand into Required Shift Units ---
  // We use a pool of "needed" shifts. 
  // We will pull from this pool to build valid associates.

  const neededShifts: ShiftUnit[] = [];

  demandData.forEach((dayData, dayIdx) => {
    const blockCapacities = TIME_BLOCKS.map(block => {
      const vol = dayData.blocks[block];
      // Capacity logic: Vol / (Prod * 4h * Util%)
      const onePersonCapacity = constraints.avgProductivity * 4 * (constraints.targetUtilization / 100);
      return Math.ceil(vol / onePersonCapacity);
    });

    const uncovered = [...blockCapacities];

    // Priority 1: Identify Full Time (8h) slots
    // We treat FT as covering 2 consecutive blocks.
    for (let i = 0; i < TIME_BLOCKS.length; i++) {
      const currentBlock = i;
      const nextBlock = (i + 1) % TIME_BLOCKS.length;

      // Simple non-wrapping logic for clarity (06-14, 10-18, etc.)
      if (i < TIME_BLOCKS.length - 1) { 
        while (uncovered[currentBlock] > 0 && uncovered[nextBlock] > 0) {
          neededShifts.push({
            day: dayData.day,
            dayIndex: dayIdx,
            blockIndex: currentBlock,
            type: 'FT',
            durationHours: 8, 
          });
          uncovered[currentBlock]--;
          uncovered[nextBlock]--;
        }
      }
    }

    // Priority 2: Identify Part Time (4h) slots
    for (let i = 0; i < TIME_BLOCKS.length; i++) {
      while (uncovered[i] > 0) {
        neededShifts.push({
          day: dayData.day,
          dayIndex: dayIdx,
          blockIndex: i,
          type: 'PT',
          durationHours: 4,
        });
        uncovered[i]--;
      }
    }
  });

  const roster: AssociateRoster[] = [];

  // Helper to find and remove a specific shift from the pool
  const popShift = (dayIdx: number, blockIdx: number, type: 'FT' | 'PT'): ShiftUnit | null => {
    const idx = neededShifts.findIndex(s => 
      s.dayIndex === dayIdx && s.blockIndex === blockIdx && s.type === type
    );
    if (idx !== -1) {
      return neededShifts.splice(idx, 1)[0];
    }
    return null;
  };

  // Helper to find ANY available shift for a given type/block preference
  // Used to greedily start a new associate
  const findSeedShift = (): ShiftUnit | undefined => {
    // Prioritize Weekend shifts to identify Weekend Warriors first?
    // User Constraint: "Weekend volumes are 30% higher".
    // Strategy: Clear strict weekend requirements first to avoid them getting swallowed by FT/PT.

    // Sort logic: Sat/Sun first, then Weekdays.
    return neededShifts.sort((a, b) => {
      const isWeekendA = a.dayIndex >= 5;
      const isWeekendB = b.dayIndex >= 5;
      if (isWeekendA && !isWeekendB) return -1;
      if (!isWeekendA && isWeekendB) return 1;
      return 0; 
    })[0];
  };


  // --- Step 2: Construct Roster with Hard Constraints ---

  // We loop until NO required shifts remain.
  let safety = 0;
  while (neededShifts.length > 0 && safety < 5000) {
    safety++;

    const seed = neededShifts[0]; // Take the first available shift (prioritized by sort above if we sorted, or just first)
    // Actually, let's specifically look for Weekend Seeds first to strictly funnel them to Weekend Warriors if they are surplus.

    // IS THIS A WEEKEND WARRIOR CANDIDATE?
    // If the seed is Sat or Sun, we try to form a Weekend Warrior (Sat+Sun).
    // Note: FT/PT can also work weekends. But if we have excessive weekend demand, we should pair it up.
    // Heuristic: If we can make a 6-day chain including this shift, do we prefer that?
    // The user wants "Optimal". 
    // Usually, 6-Day FT is more efficient than Weekend Warrior if the demand exists M-F.

    // Let's try to form a 6-Day Chain (FT or PT) starting with this seed.
    // A 6-day chain needs 5 other days.
    // We look for the "Best" 5 other days (highest availability).

    // Check availability for this BlockIndex & Type across the week
    const availabilityByDay = Array(7).fill(false);
    neededShifts.forEach(s => {
      if (s.blockIndex === seed.blockIndex && s.type === seed.type) {
        availabilityByDay[s.dayIndex] = true;
      }
    });

    const daysAvailableCount = availabilityByDay.filter(Boolean).length;

    // DECISION LOGIC:
    // 1. If we have availability for >= 4 days, likely a FT/PT 6-day role.
    // 2. If we only have availability on Sat/Sun (or scattered), likely a Weekend Warrior or Fragment.

    let assigned = false;

    // STRATEGY A: Try to build a 6-Day Roster (Strict 48h / 24h)
    // We do this if it's a Weekday seed OR if we have enough days to justify it.
    if (daysAvailableCount >= 3 || (seed.dayIndex < 5)) {
      // Try to find 6 days.
      // We prioritize days that HAVE demand.
      // If we don't have 6 days of demand, we OVERSTAFF (Pick days with 0 demand) to meet the contract.

      const workDaysSet = new Set<number>();

      // 1. Take all available days (up to 6)
      for(let d=0; d<7; d++) {
        if (availabilityByDay[d] && workDaysSet.size < 6) {
          workDaysSet.add(d);
        }
      }

      // 2. If we have < 6, fill with random other days (Overstaffing)
      // Prefer Weekdays for fill? Or just sequential?
      for(let d=0; d<7; d++) {
        if (workDaysSet.size < 6 && !workDaysSet.has(d)) {
          workDaysSet.add(d);
        }
      }

      // Create the Associate
      if (workDaysSet.size === 6) {
        const newAssociate: AssociateRoster = {
          id: generateId(),
          name: 'Temp',
          role: seed.type === 'FT' ? 'Full Time' : 'Part Time',
          schedule: { Mon: 'OFF', Tue: 'OFF', Wed: 'OFF', Thu: 'OFF', Fri: 'OFF', Sat: 'OFF', Sun: 'OFF' },
          totalHours: 0
        };

        workDaysSet.forEach(dIdx => {
          const dayName = getDayName(dIdx);
          // Try to pop a real shift
          const realShift = popShift(dIdx, seed.blockIndex, seed.type);

          if (realShift) {
            newAssociate.schedule[dayName] = formatShiftTime(realShift.blockIndex, realShift.type);
            newAssociate.totalHours += realShift.durationHours;
          } else {
            // Overstaff logic: Create a ghost shift to satisfy contract
            newAssociate.schedule[dayName] = formatShiftTime(seed.blockIndex, seed.type);
            newAssociate.totalHours += seed.durationHours; // 8 or 4
          }
        });
        roster.push(newAssociate);
        assigned = true;
      }
    }

    // STRATEGY B: Weekend Warrior (Strict Sat+Sun)
    // If Strategy A failed (e.g. couldn't form logic) OR it was a pure weekend seed we decided to skip A for.
    if (!assigned) {
      // Strict Sat (5) + Sun (6)
      const newAssociate: AssociateRoster = {
        id: generateId(),
        name: 'Temp',
        role: 'Weekend Warrior',
        schedule: { Mon: 'OFF', Tue: 'OFF', Wed: 'OFF', Thu: 'OFF', Fri: 'OFF', Sat: 'OFF', Sun: 'OFF' },
        totalHours: 0
      };

      // Handle Sat
      const satShift = popShift(5, seed.blockIndex, seed.type);
      if (satShift) {
        newAssociate.schedule['Sat'] = formatShiftTime(satShift.blockIndex, satShift.type);
        newAssociate.totalHours += satShift.durationHours;
      } else {
        // Force Sat if we are making this role (e.g. seed was Sun)
        newAssociate.schedule['Sat'] = formatShiftTime(seed.blockIndex, seed.type);
        newAssociate.totalHours += seed.durationHours;
      }

      // Handle Sun
      const sunShift = popShift(6, seed.blockIndex, seed.type);
      if (sunShift) {
        newAssociate.schedule['Sun'] = formatShiftTime(sunShift.blockIndex, sunShift.type);
        newAssociate.totalHours += sunShift.durationHours;
      } else {
        // Force Sun if we are making this role (e.g. seed was Sat)
        newAssociate.schedule['Sun'] = formatShiftTime(seed.blockIndex, seed.type);
        newAssociate.totalHours += seed.durationHours;
      }

      roster.push(newAssociate);
      assigned = true;
    }
  }

  // --- Step 3: Sort & Rename ---
  const rolePriority: Record<string, number> = { 
    'Full Time': 1, 
    'Part Time': 2, 
    'Weekend Warrior': 3 
  };

  roster.sort((a, b) => {
    // 1. Role
    const roleDiff = (rolePriority[a.role] || 99) - (rolePriority[b.role] || 99);
    if (roleDiff !== 0) return roleDiff;
    // 2. Total Hours (just to keep clean)
    return b.totalHours - a.totalHours;
  });

  roster.forEach((associate, index) => {
    associate.name = `Associate ${index + 1}`;
  });

  // --- Step 4: Stats & Summary ---
  const totalVolume = demandData.reduce((sum, d) => sum + Object.values(d.blocks).reduce((a, b) => a + b, 0), 0);
  const totalHours = roster.reduce((sum, a) => sum + a.totalHours, 0);

  // Note: Utilization might exceed 100% or drop below 100% depending on overstaffing.
  // Real Utilization = Required Hours / Actual Roster Hours.
  // If we overstaffed, Actual > Required, so Util < 100%.

  // Calculate raw required hours from volume
  const requiredHours = totalVolume / constraints.avgProductivity;
  const calculatedUtilization = totalHours > 0 ? (requiredHours / totalHours) * 100 : 0;

  const ftCount = roster.filter(a => a.role === 'Full Time').length;
  const ptCount = roster.filter(a => a.role === 'Part Time').length;
  const wkCount = roster.filter(a => a.role === 'Weekend Warrior').length;

  const summary = `Optimization Algorithm Methodology (Strict Constraints Mode):

1. Strict Contract Enforcement:
- Full Time associates are GUARANTEED 48 hours (6 days × 8h).
- Part Time associates are GUARANTEED 24 hours (6 days × 4h).
- Weekend Warriors are GUARANTEED coverage for both Saturday and Sunday.

2. Gap Filling (Overstaffing):
To meet the hard constraints above, the algorithm may assign shifts on days with zero remaining demand if a perfect 6-day chain cannot be found. This prioritizes contract stability over raw daily efficiency.

3. Role Mix:
- Base Load: Covered by Full Time staff working 6-day rotations.
- Variable/Peak Load: Covered by Part Time staff working 6-day rotations.
- Weekend Spike: Specifically targeted by Weekend Warriors (Sat+Sun) to preserve week-off flexibility for the core team.

Outcome:
Generated a roster with ${ftCount} Full-Time, ${ptCount} Part-Time, and ${wkCount} Weekend Warriors.
Blended Utilization: ${calculatedUtilization.toFixed(1)}% (May be <100% due to strict contract enforcement)`;

  return {
    strategySummary: summary,
    weeklyStats: {
      totalVolume,
      totalHeadcount: roster.length,
      blendedUtilization: calculatedUtilization, 
      mix: { ft: ftCount, pt: ptCount, weekend: wkCount }
    },
    roster,
    recommendations: [
      "All Full Time staff work exactly 48 hours.",
      "All Part Time staff work exactly 24 hours.",
      "Weekend Warriors cover both Sat & Sun."
    ]
  };
};

// --- Helpers ---

const getDayName = (idx: number): DayOfWeek => {
  const days: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  return days[idx];
}

const formatShiftTime = (startIndex: number, type: 'FT' | 'PT'): string => {
  const startHour = 6 + (startIndex * 4);
  const duration = type === 'FT' ? 9 : 4; 
  const endHour = (startHour + duration) % 24;

  const format = (h: number) => `${h.toString().padStart(2, '0')}:00`;
  const startStr = format(startHour >= 24 ? startHour - 24 : startHour);
  const endStr = format(endHour);

  return `${startStr}-${endStr}`;
};

