import React, { useState, useMemo } from 'react';
import { StaffingSolution, DemandData, Constraints, TIME_BLOCKS, DayOfWeek } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { CheckCircle2, Users, Clock, CalendarDays, BarChart2 } from 'lucide-react';

interface SolutionDashboardProps {
  solution: StaffingSolution;
  demand: DemandData[];
  constraints: Constraints;
}

const SolutionDashboard: React.FC<SolutionDashboardProps> = ({ solution, demand, constraints }) => {
  const [view, setView] = useState<'overview' | 'roster' | 'heatmap'>('overview');

  const mixData = [
    { name: 'Full Time', value: solution.weeklyStats.mix.ft, color: '#3b82f6' },
    { name: 'Part Time', value: solution.weeklyStats.mix.pt, color: '#10b981' },
    { name: 'Weekend Only', value: solution.weeklyStats.mix.weekend, color: '#f59e0b' },
  ].filter(d => d.value > 0);

  const days: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  // Calculate Heatmap Data
  const heatmapData = useMemo(() => {
    // 1. Initialize Supply Matrix
    const supply: Record<string, Record<string, number>> = {};
    days.forEach(d => {
      supply[d] = {};
      TIME_BLOCKS.forEach(b => supply[d][b] = 0);
    });

    // 2. Populate Supply from Roster
    solution.roster.forEach(associate => {
      days.forEach(day => {
        const scheduleStr = associate.schedule[day];
        if (scheduleStr === 'OFF') return;

        // Parse start hour from "HH:00-HH:00"
        const startHour = parseInt(scheduleStr.split(':')[0]);
        // Map start hour to block index: (Start - 6) / 4
        // Wrap around 24h logic if needed, but standard blocks are 06, 10, 14, 18, 22, 02
        let blockIndex = -1;
        if (startHour >= 6) blockIndex = (startHour - 6) / 4;
        else if (startHour === 2) blockIndex = 5; // 02:00 is index 5

        if (blockIndex >= 0 && blockIndex < 6) {
          // Add capacity to the starting block
          supply[day][TIME_BLOCKS[blockIndex]] += 1;

          // If FT, they work 2 blocks (8 hours)
          if (associate.role === 'Full Time') {
             const nextBlockIndex = (blockIndex + 1) % 6;
             supply[day][TIME_BLOCKS[nextBlockIndex]] += 1;
          }
        }
      });
    });

    // 3. Calculate Utilization
    // Util % = Volume / (Supply * Productivity * 4 hours) 
    // Wait, productivity is usually units/hr. Block is 4 hours. Capacity = Heads * Prod * 4.
    const utilization: Record<string, Record<string, number>> = {};

    days.forEach((day, dayIdx) => {
      utilization[day] = {};
      const dayDemand = demand[dayIdx]; // Assuming demand array order matches days array

      TIME_BLOCKS.forEach(block => {
        const volume = dayDemand.blocks[block];
        const heads = supply[day][block];
        const capacity = heads * constraints.avgProductivity * 4; // 4 hour block

        if (volume === 0) utilization[day][block] = 0;
        else if (capacity === 0) utilization[day][block] = 999; // Infinite/Error
        else utilization[day][block] = Math.round((volume / capacity) * 100);
      });
    });

    return utilization;
  }, [solution, demand, constraints]);

  const getHeatmapColor = (util: number) => {
    if (util === 999) return 'bg-red-600 text-white'; // Uncovered
    if (util > 105) return 'bg-red-500 text-white'; // Understaffed
    if (util >= 80) return 'bg-emerald-500 text-white'; // Optimal
    if (util >= 50) return 'bg-blue-400 text-white'; // Slightly Overstaffed
    if (util > 0) return 'bg-blue-200 text-slate-700'; // Overstaffed
    return 'bg-slate-100 text-slate-400'; // No volume
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-700">

      {/* Sub-Navigation */}
      <div className="flex items-center justify-between border-b border-slate-200 pb-4">
        <div className="flex gap-2">
          <button
            onClick={() => setView('overview')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'overview' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Overview & Stats
          </button>
          <button
            onClick={() => setView('heatmap')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'heatmap' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Utilization Heatmap
          </button>
          <button
            onClick={() => setView('roster')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'roster' ? 'bg-indigo-100 text-indigo-700' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Detailed Roster
          </button>
        </div>
        <div className="text-sm text-slate-500">
           Total Headcount: <strong>{solution.weeklyStats.totalHeadcount}</strong>
        </div>
      </div>

      {view === 'overview' && (
        <div className="space-y-6">
          {/* KPI Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-blue-50 rounded-lg">
                  <Users className="w-5 h-5 text-blue-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Total Hours</span>
              </div>
              <div className="text-2xl font-bold text-slate-900">
                {solution.roster.reduce((acc, r) => acc + r.totalHours, 0).toLocaleString()} <span className="text-sm font-normal text-slate-400">hrs/wk</span>
              </div>
            </div>

            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-emerald-50 rounded-lg">
                  <Clock className="w-5 h-5 text-emerald-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Efficiency</span>
              </div>
              <div className="text-2xl font-bold text-slate-900">
                {solution.weeklyStats.blendedUtilization.toFixed(1)}% <span className="text-sm font-normal text-slate-400">utilization</span>
              </div>
            </div>

            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
               <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-amber-50 rounded-lg">
                  <CalendarDays className="w-5 h-5 text-amber-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Staffing Mix</span>
              </div>
              <div className="text-sm text-slate-700 mt-1">
                <span className="font-semibold">{solution.weeklyStats.mix.ft}</span> FT, {' '}
                <span className="font-semibold">{solution.weeklyStats.mix.pt}</span> PT, {' '}
                <span className="font-semibold">{solution.weeklyStats.mix.weekend}</span> Wknd
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/* Strategy Text */}
            <div className="md:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="text-lg font-semibold text-slate-800 mb-3">Optimization Strategy</h3>
              <p className="text-slate-600 leading-relaxed text-sm whitespace-pre-wrap font-sans">{solution.strategySummary}</p>

              <h4 className="font-medium text-slate-800 mt-6 mb-3">Key Recommendations</h4>
              <ul className="space-y-2">
                {solution.recommendations.map((rec, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-sm text-slate-600">
                    <CheckCircle2 className="w-4 h-4 text-emerald-500 mt-0.5 flex-shrink-0" />
                    {rec}
                  </li>
                ))}
              </ul>
            </div>

            {/* Mix Chart */}
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center">
              <h3 className="text-sm font-semibold text-slate-800 mb-2 w-full text-left">Headcount Mix</h3>
              <div className="w-full h-48">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={mixData}
                      cx="50%"
                      cy="50%"
                      innerRadius={40}
                      outerRadius={70}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {mixData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" height={36} iconSize={8} wrapperStyle={{ fontSize: '12px' }}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>
      )}

      {view === 'heatmap' && (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex items-center gap-2 mb-6">
            <BarChart2 className="w-5 h-5 text-indigo-600" />
            <h3 className="text-lg font-semibold text-slate-800">Intra-Day Utilization Heatmap</h3>
          </div>

          <div className="flex justify-end gap-4 mb-4 text-xs font-medium text-slate-600">
            <div className="flex items-center gap-1"><div className="w-3 h-3 bg-emerald-500 rounded"></div> Optimal (80-105%)</div>
            <div className="flex items-center gap-1"><div className="w-3 h-3 bg-blue-400 rounded"></div> Relaxed (50-79%)</div>
            <div className="flex items-center gap-1"><div className="w-3 h-3 bg-blue-200 rounded"></div> Low (&lt;50%)</div>
            <div className="flex items-center gap-1"><div className="w-3 h-3 bg-red-500 rounded"></div> Understaffed (&gt;105%)</div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left border-collapse">
              <thead>
                <tr>
                  <th className="p-3 bg-slate-50 border border-slate-200 text-slate-500 font-medium">Day</th>
                  {TIME_BLOCKS.map(block => (
                    <th key={block} className="p-3 bg-slate-50 border border-slate-200 text-center text-slate-500 font-medium min-w-[100px]">
                      {block}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {days.map(day => (
                  <tr key={day}>
                    <td className="p-3 border border-slate-200 font-semibold text-slate-700 bg-slate-50">{day}</td>
                    {TIME_BLOCKS.map(block => {
                      const util = heatmapData[day][block];
                      return (
                        <td key={`${day}-${block}`} className={`p-3 border border-white text-center font-bold transition-colors ${getHeatmapColor(util)}`}>
                          {util === 999 ? 'GAP' : `${util}%`}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <p className="text-xs text-slate-400 mt-4 italic">
            * Utilization = Demand Volume / (Scheduled Staff * Productivity * 4hrs). 100% means perfect alignment.
          </p>
        </div>
      )}

      {view === 'roster' && (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left">
              <thead className="bg-slate-50 text-slate-500 font-medium border-b border-slate-200">
                <tr>
                  <th className="px-4 py-3 sticky left-0 bg-slate-50 z-20">Associate Name</th>
                  <th className="px-4 py-3 sticky left-[120px] bg-slate-50 z-20 shadow-r">Role</th>
                  {days.map(d => (
                    <th key={d} className="px-2 py-3 text-center min-w-[100px]">{d}</th>
                  ))}
                  <th className="px-4 py-3 text-right">Hrs</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {solution.roster.map((person) => (
                  <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-4 py-2 font-medium text-slate-800 sticky left-0 bg-white z-10 whitespace-nowrap">
                      {person.name}
                    </td>
                    <td className="px-4 py-2 sticky left-[120px] bg-white z-10 whitespace-nowrap">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-medium ${
                        person.role === 'Full Time' ? 'bg-blue-100 text-blue-700' :
                        person.role === 'Part Time' ? 'bg-emerald-100 text-emerald-700' :
                        'bg-amber-100 text-amber-700'
                      }`}>
                        {person.role}
                      </span>
                    </td>
                    {days.map(d => (
                      <td key={d} className="px-2 py-2 text-center">
                        {/* @ts-ignore */}
                        <div className={`py-1 px-1 rounded ${
                           // @ts-ignore
                          person.schedule[d] === 'OFF' 
                            ? 'bg-slate-100 text-slate-400' 
                            : 'bg-indigo-50 text-indigo-700 font-medium'
