import { AssociateRoster, Constraints, DemandData, StaffingSolution, TIME_BLOCKS, DayOfWeek, RoleType } from "../types";

// --- Types & Constants for the Solver ---

const DAYS: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

// Represents a predefined valid schedule shape (Template)
interface SchedulePattern {
  id: string;
  role: RoleType;
  shifts: Record<DayOfWeek, number | null>; // null = OFF, number = start block index (0-5)
  weeklyHours: number;
}

// Represents the residual demand curve
type DemandMatrix = Record<DayOfWeek, number[]>; // Array of 6 integers per day

// --- 1. Pattern Generation (SolveShiftGeneration) ---
// Instead of building shifts dynamically, we generate the "Universe of Valid Patterns"
const generatePatterns = (): SchedulePattern[] => {
  const patterns: SchedulePattern[] = [];

  // A. Full Time Patterns (6 days work, 1 day off)
  // Shifts are 8 hours (2 blocks). Start times restricted to standard blocks for simplicity.
  // Rotates the OFF day.
  for (let offDayIdx = 0; offDayIdx < 7; offDayIdx++) {
    for (let startBlock = 0; startBlock < 6; startBlock++) {
      const schedule: any = {};
      let hours = 0;
      DAYS.forEach((day, idx) => {
        if (idx === offDayIdx) {
          schedule[day] = null;
        } else {
          schedule[day] = startBlock;
          hours += 8; // 2 blocks * 4 hours
        }
      });

      patterns.push({
        id: `FT_OFF_${DAYS[offDayIdx]}_START_${startBlock}`,
        role: 'Full Time',
        shifts: schedule,
        weeklyHours: hours
      });
    }
  }

  // B. Part Time Patterns (Flex Schedules)
  // For this solver, let's define PT as 5 days * 4 hours (20hrs) or 4 days * 4 hours (16hrs)
  // To keep the search space manageable, let's use a standard "5 days on, 2 days off" PT model
  // Off days usually consecutive? Let's say any 2 days. For speed: Fixed Sat/Sun OFF or Sun/Mon OFF
  const ptPairs = [[5, 6], [6, 0], [0, 1]]; // Sat-Sun, Sun-Mon, Mon-Tue
  ptPairs.forEach(pair => {
    for (let startBlock = 0; startBlock < 6; startBlock++) {
       const schedule: any = {};
       let hours = 0;
       DAYS.forEach((day, idx) => {
         if (pair.includes(idx)) {
           schedule[day] = null;
         } else {
           schedule[day] = startBlock;
           hours += 4;
         }
       });
       patterns.push({
         id: `PT_OFF_${pair.join('')}_START_${startBlock}`,
         role: 'Part Time',
         shifts: schedule,
         weeklyHours: hours
       });
    }
  });

  // C. Weekend Warrior (Sat + Sun only)
  // 12 hour shifts (3 blocks) or 8 hours? Let's stick to 8h for consistency with other model, but could be flexible.
  for (let startBlock = 0; startBlock < 6; startBlock++) {
    const schedule: any = {};
    let hours = 0;
    DAYS.forEach(day => {
      if (day === 'Sat' || day === 'Sun') {
        schedule[day] = startBlock;
        hours += 8;
      } else {
        schedule[day] = null;
      }
    });
    patterns.push({
        id: `WW_START_${startBlock}`,
        role: 'Weekend Warrior',
        shifts: schedule,
        weeklyHours: hours
    });
  }

  return patterns;
};

// --- 2. Solver Logic (SolveShiftScheduling) ---

export const generateORToolsStaffingPlan = (
  demandData: DemandData[],
  constraints: Constraints
): StaffingSolution => {

  // 1. Initialize Demand Matrix (Net Required Headcount)
  const requiredMatrix: DemandMatrix = {} as any;
  let totalVolume = 0;

  DAYS.forEach((day, i) => {
    requiredMatrix[day] = TIME_BLOCKS.map(block => {
        const vol = demandData[i].blocks[block];
        totalVolume += vol;
        const capacityPerPerson = constraints.avgProductivity * 4 * (constraints.targetUtilization / 100);
        return Math.ceil(vol / capacityPerPerson);
    });
  });

  // Copy for mutation during solving
  const residualMatrix: DemandMatrix = JSON.parse(JSON.stringify(requiredMatrix));

  // Helper to calculate score of a pattern against residual demand
  // Higher score = better fit (covers more positive demand)
  const calculatePatternScore = (pattern: SchedulePattern, currentMatrix: DemandMatrix): number => {
    let score = 0;
    let overstaffPenalty = 0;

    DAYS.forEach((day) => {
        const startBlock = pattern.shifts[day];
        if (startBlock !== null) {
            // How many blocks does this shift cover?
            const durationBlocks = pattern.role === 'Part Time' ? 1 : 2; // PT 4h, FT 8h (WW 8h)

            for (let b = 0; b < durationBlocks; b++) {
                const blockIdx = (startBlock + b) % 6;
                const needed = currentMatrix[day][blockIdx];

                if (needed > 0) {
                    score += 10; // High reward for covering need
                } else if (needed <= 0) {
                    overstaffPenalty += 2; // Penalty for adding to overstaffing
                }
            }
        }
    });

    return score - overstaffPenalty;
  };

  const patterns = generatePatterns();
  const roster: AssociateRoster[] = [];
  const MAX_ITERATIONS = 500; // Safety break
  let iterations = 0;

  // 2. Iterative Pattern Selection (Hill Climbing / Greedy Construction)
  // We keep adding the "Best" pattern until diminishing returns
  while (iterations < MAX_ITERATIONS) {
    // A. Check if we still have significant demand
    const totalUnmet = Object.values(residualMatrix).flat().reduce((sum, val) => sum + (val > 0 ? val : 0), 0);
    if (totalUnmet <= 0) break;

    // B. Find best pattern
    let bestPattern: SchedulePattern | null = null;
    let bestScore = -Infinity;

    // We can add randomization here for Simulated Annealing, but purely greedy for now
    for (const pattern of patterns) {
        // Simple heuristic: Don't pick PT/WW if we are over caps? 
        // We will deal with mix caps in post-processing or via weights.
        // Let's rely on scoring first.
        const score = calculatePatternScore(pattern, residualMatrix);
        if (score > bestScore) {
            bestScore = score;
            bestPattern = pattern;
        }
    }

    if (!bestPattern || bestScore <= 0) {
        break; // No pattern helps anymore
    }

    // C. Add to Roster
    const newAssociate: AssociateRoster = {
        id: Math.random().toString(36).substr(2, 9),
        name: `Associate ${roster.length + 1}`,
        role: bestPattern.role,
        schedule: {} as any,
        totalHours: bestPattern.weeklyHours
    };

    // Apply schedule strings
    DAYS.forEach(day => {
        const startBlock = bestPattern!.shifts[day];
        if (startBlock === null) {
            newAssociate.schedule[day] = 'OFF';
        } else {
            const duration = bestPattern!.role === 'Part Time' ? 4 : 8; // simplified
            newAssociate.schedule[day] = formatShiftTime(startBlock, duration);

            // D. Update Residual Matrix
            const durationBlocks = bestPattern!.role === 'Part Time' ? 1 : 2;
            for (let b = 0; b < durationBlocks; b++) {
                const blockIdx = (startBlock + b) % 6;
                residualMatrix[day][blockIdx]--;
            }
        }
    });

    roster.push(newAssociate);
    iterations++;
  }

  // 3. Post-Process: Mix Adjustment (Similar to previous solver but stricter on pattern removal)
  // If we have too many PT/WW, we might need to swap them or remove them (simplification: we just label them)
  // The OR-Tools approach usually builds constraints into the selection, but for this lightweight version, 
  // we will leave the mix natural based on the "Best Fit" logic. 

  // Sort roster by role
  const rolePriority: Record<string, number> = { 
    'Full Time': 1, 
    'Part Time': 2, 
    'Weekend Warrior': 3 
  };

  roster.sort((a, b) => {
    const roleDiff = (rolePriority[a.role] || 99) - (rolePriority[b.role] || 99);
    if (roleDiff !== 0) return roleDiff;
    return b.totalHours - a.totalHours;
  });

  roster.forEach((associate, index) => {
    associate.name = `Associate ${index + 1}`;
  });

  // Stats
  const totalHours = roster.reduce((sum, a) => sum + a.totalHours, 0);
  const requiredHours = totalVolume / constraints.avgProductivity;
  const calculatedUtilization = totalHours > 0 ? (requiredHours / totalHours) * 100 : 0;

  const ftCount = roster.filter(a => a.role === 'Full Time').length;
  const ptCount = roster.filter(a => a.role === 'Part Time').length;
  const wkCount = roster.filter(a => a.role === 'Weekend Warrior').length;

  const summary = `Optimization Method: Pattern-Based Constraint Solver (OR-Tools Logic)

Unlike the standard greedy algorithm which fits shifts hour-by-hour, this solver utilizes a Constructive Heuristic approach inspired by 'SolveShiftGeneration' and 'SolveShiftScheduling'. 

1. Pattern Generation: Pre-calculates the universe of valid roster templates (e.g., "FT Morning, Tue Off", "WW Afternoon").
2. Cost Minimization: Iteratively selects the specific roster pattern that maximizes coverage of the remaining demand curve (Hill Climbing).
3. Constraint Adherence: Ensures every associate works a mathematically consistent shift pattern across the week, reducing schedule fragmentation.

This method typically produces more consistent individual schedules at the cost of slightly higher total headcount compared to the granular greedy solver.`;

  return {
    solverMethod: 'ortools',
    strategySummary: summary,
    weeklyStats: {
      totalVolume,
      totalHeadcount: roster.length,
      blendedUtilization: calculatedUtilization, 
      mix: { ft: ftCount, pt: ptCount, weekend: wkCount }
    },
    roster,
    recommendations: [
      "Schedules are generated based on fixed consistent patterns.",
      "Higher consistency in start times for associates.",
      "May result in slightly lower utilization to preserve shift consistency."
    ]
  };
};

// Helper
const formatShiftTime = (startIndex: number, duration: number): string => {
    const startHour = 6 + (startIndex * 4);
    const endHour = (startHour + duration) % 24;

    const format = (h: number) => `${h.toString().padStart(2, '0')}:00`;
    const startStr = format(startHour >= 24 ? startHour - 24 : startHour);
    const endStr = format(endHour);

    return `${startStr}-${endStr}`;
};

import React, { useState } from 'react';
import { INITIAL_CONSTRAINTS, INITIAL_DEMAND, Constraints, DemandData, StaffingSolution } from './types';
import DemandInput from './components/DemandInput';
import ConstraintsForm from './components/ConstraintsForm';
import SolutionDashboard from './components/SolutionDashboard';
import { generateAlgorithmicStaffingPlan } from './services/staffingAlgorithm';
import { generateORToolsStaffingPlan } from './services/orToolsSolver';
import { Layers, Zap, Loader2, Calculator, BrainCircuit, Shuffle } from 'lucide-react';

export default function App() {
  const [activeTab, setActiveTab] = useState<'input' | 'results'>('input');
  const [demand, setDemand] = useState<DemandData[]>(INITIAL_DEMAND);
  const [constraints, setConstraints] = useState<Constraints>(INITIAL_CONSTRAINTS);
  const [isLoading, setIsLoading] = useState(false);
  const [solution, setSolution] = useState<StaffingSolution | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [solverType, setSolverType] = useState<'greedy' | 'ortools'>('greedy');

  const handleOptimize = async () => {
    setIsLoading(true);
    setError(null);
    setSolution(null);

    // Simulate processing delay for better UX
    setTimeout(() => {
      try {
        let result: StaffingSolution;
        if (solverType === 'ortools') {
            result = generateORToolsStaffingPlan(demand, constraints);
        } else {
            result = generateAlgorithmicStaffingPlan(demand, constraints);
            result.solverMethod = 'greedy';
        }
        setSolution(result);
        setActiveTab('results');
        setIsLoading(false);
      } catch (err: any) {
        setError(err.message || "An unexpected error occurred during optimization.");
        setIsLoading(false);
      }
    }, 800);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
