                  </div>
                  <p className="text-slate-400 text-xs mt-2 italic">
                     {solverType === 'greedy' ? 'Best for precise gap filling and strict efficiency.' : 'Best for consistent shift patterns and smoother rosters.'}
                  </p>
                </div>

                <button
                  onClick={handleOptimize}
                  disabled={isLoading}
