           schedule[day] = startBlock;
           hours += 4;
         }
       });
       patterns.push({
         id: `PT_OFF_${DAYS[offDayIdx]}_START_${startBlock}`,
         role: 'Part Time',
         shifts: schedule,
         weeklyHours: hours,
         shiftDuration: 4
       });
    }
  }

  // C. Weekend Warrior (Sat + Sun only)
  // Constraint: Must work Sat AND Sun.
  // Shift: 9 hours.
  for (let startBlock = 0; startBlock < 6; startBlock++) {
    const schedule: any = {};
    let hours = 0;
    DAYS.forEach(day => {
      if (day === 'Sat' || day === 'Sun') {
        schedule[day] = startBlock;
        hours += 9; // 9 hours paid
      } else {
        schedule[day] = null;
      }
    });
    patterns.push({
        id: `WW_START_${startBlock}`,
        role: 'Weekend Warrior',
        shifts: schedule,
        weeklyHours: hours,
        shiftDuration: 9
    });
  }

  return patterns;
};

