          <nav className="flex items-center gap-1 bg-slate-100 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('input')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${
                activeTab === 'input' 
                  ? 'bg-white text-indigo-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Model Inputs
            </button>
            <button
              onClick={() => solution && setActiveTab('results')}
              disabled={!solution}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${
                activeTab === 'results' 
                  ? 'bg-white text-indigo-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700 disabled:opacity-50'
              }`}
            >
              Results
            </button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
            <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-2">
                <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                {error}
            </div>
        )}

        {activeTab === 'input' && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-bottom-4 duration-500">
            <div className="lg:col-span-2 space-y-6">
              <DemandInput 
                demand={demand} 
                onChange={setDemand} 
                weekendSpike={constraints.weekendSpike} 
              />

              <div className="p-6 rounded-xl shadow-lg transition-colors bg-slate-800 text-white flex flex-col items-stretch justify-between gap-6">
                <div>
                  <h3 className="text-lg font-semibold mb-2 flex items-center gap-2">
                    <Zap className="w-5 h-5 text-yellow-400" />
                    Staffing Engine Configuration
                  </h3>

                  <div className="flex flex-wrap items-center gap-3 mt-3">
                    <button 
                        onClick={() => setSolverType('greedy')}
                        className={`text-xs px-4 py-2.5 rounded-lg transition-all flex items-center gap-2 border ${solverType === 'greedy' ? 'bg-indigo-600 border-indigo-500 text-white font-bold' : 'bg-slate-900 border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <Calculator className="w-3.5 h-3.5" />
                        Greedy Deterministic
                    </button>
                    <button 
                        onClick={() => setSolverType('ortools')}
                        className={`text-xs px-4 py-2.5 rounded-lg transition-all flex items-center gap-2 border ${solverType === 'ortools' ? 'bg-purple-600 border-purple-500 text-white font-bold' : 'bg-slate-900 border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <Shuffle className="w-3.5 h-3.5" />
                        Pattern Solver (OR-Tools)
                    </button>
                    <button 
                        onClick={() => setSolverType('frugal')}
                        className={`text-xs px-4 py-2.5 rounded-lg transition-all flex items-center gap-2 border ${solverType === 'frugal' ? 'bg-amber-600 border-amber-500 text-white font-bold' : 'bg-slate-900 border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <Coins className="w-3.5 h-3.5" />
                        Frugal Optimizer (MIP)
                    </button>
                  </div>
                  <p className="text-slate-400 text-xs mt-3 italic bg-slate-900/40 p-2 rounded border border-slate-700/50">
                     {solverType === 'greedy' && 'Best for precise gap filling and strict efficiency.'}
                     {solverType === 'ortools' && 'Best for consistent shift patterns and smoother rosters.'}
                     {solverType === 'frugal' && 'Advanced: Optimizes 24 start-hour slots to minimize structural waste.'}
                  </p>
                </div>

                <button
                  onClick={handleOptimize}
                  disabled={isLoading}
                  className={`w-full text-white font-bold py-4 px-6 rounded-xl transition-all flex items-center justify-center gap-3 disabled:opacity-70 disabled:cursor-not-allowed shadow-xl ${
                    solverType === 'ortools' ? 'bg-purple-600 hover:bg-purple-700 shadow-purple-900/20' : 
                    solverType === 'frugal' ? 'bg-amber-600 hover:bg-amber-700 shadow-amber-900/20' : 
                    'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-900/20'
                  }`}
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-6 h-6 animate-spin" />
                      Crunching Logistics Data...
                    </>
                  ) : (
                    <>
                      <BrainCircuit className="w-6 h-6" />
                      Run {solverType === 'frugal' ? 'Frugal MIP' : 'Solver'}
                    </>
                  )}
                </button>
              </div>
            </div>

            <div className="space-y-6">
              <ConstraintsForm constraints={constraints} onChange={setConstraints} />

              <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                <h3 className="text-sm font-medium text-slate-700 mb-3 flex items-center gap-2">
                  <BrainCircuit className="w-4 h-4 text-indigo-500" />
                  Methodology Selection
                </h3>
                <div className="p-3 bg-slate-50 rounded-lg border border-slate-100">
                  <div className="flex items-start gap-3">
                    {solverType === 'greedy' && <Calculator className="w-5 h-5 text-indigo-600 mt-0.5" />}
                    {solverType === 'ortools' && <Shuffle className="w-5 h-5 text-purple-600 mt-0.5" />}
                    {solverType === 'frugal' && <Coins className="w-5 h-5 text-amber-600 mt-0.5" />}
                    <div>
                      <p className="text-sm font-medium text-slate-900">
                        {solverType === 'greedy' ? 'Deterministic Greedy' : solverType === 'ortools' ? 'Pattern-Based (OR-Tools)' : 'Frugal MIP-Lite'}
                      </p>
                      <p className="text-xs text-slate-500 mt-1">
                        {solverType === 'greedy' && 'Direct sequential mapping of shifts to demand blocks.'} 
                        {solverType === 'ortools' && 'Selection of optimal 6-day patterns to maximize roster stability.'}
                        {solverType === 'frugal' && 'Iterative global optimization across 24 hourly start-time vectors.'}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'results' && solution && (
          <SolutionDashboard 
            solution={solution} 
            demand={demand}
            constraints={constraints}
          />
        )}
      </main>

      <footer className="py-6 px-4 sm:px-6 lg:px-8 mt-auto border-t border-slate-100 bg-white/50">
         <div className="max-w-7xl mx-auto w-full flex justify-between items-center">
            <p className="text-slate-400 text-[10px] font-bold tracking-widest uppercase">neelshekhar / staffoptima v2.5</p>
            <div className="flex gap-4">
               <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
               <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
               <div className="w-2 h-2 rounded-full bg-purple-500"></div>
            </div>
         </div>
      </footer>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { StaffingSolution, DemandData, Constraints, TIME_BLOCKS, DayOfWeek } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { 
  CheckCircle2, Users, Clock, CalendarDays, BarChart2, 
  Activity, TrendingUp, TrendingDown, Sparkles, BookOpen, 
  ChevronRight, Target, Workflow, Scale, Info, Lightbulb,
  Coins, Zap, TrendingUp as TrendUp
} from 'lucide-react';

interface SolutionDashboardProps {
  solution: StaffingSolution;
  demand: DemandData[];
  constraints: Constraints;
}

const SolutionDashboard: React.FC<SolutionDashboardProps> = ({ solution, demand, constraints }) => {
  const [view, setView] = useState<'overview' | 'roster' | 'heatmap' | 'explanation' | 'frugal'>('overview');
  const isOrTools = solution.solverMethod === 'ortools';
  const isFrugal = solution.solverMethod === 'frugal';

  const themeColor = isFrugal ? 'text-amber-600' : isOrTools ? 'text-purple-600' : 'text-indigo-600';
  const themeBg = isFrugal ? 'bg-amber-50' : isOrTools ? 'bg-purple-50' : 'bg-indigo-50';
  const themeButton = isFrugal ? 'bg-amber-100 text-amber-700' : isOrTools ? 'bg-purple-100 text-purple-700' : 'bg-indigo-100 text-indigo-700';

  const mixData = [
    { name: 'Full Time', value: solution.weeklyStats.mix.ft, color: isFrugal ? '#d97706' : isOrTools ? '#9333ea' : '#3b82f6' },
    { name: 'Part Time', value: solution.weeklyStats.mix.pt, color: '#10b981' },
    { name: 'Weekend Only', value: solution.weeklyStats.mix.weekend, color: '#f59e0b' },
  ].filter(d => d.value > 0);

  const days: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  const simulationFacts = useMemo(() => {
    let maxVol = 0;
    let maxDay = 'Mon';
    let maxBlock = '06:00-10:00';

    demand.forEach(d => {
      Object.entries(d.blocks).forEach(([block, vol]) => {
        if (vol > maxVol) {
          maxVol = vol;
          maxDay = d.day;
          maxBlock = block;
        }
      });
    });

    const ftCount = solution.weeklyStats.mix.ft;
    const ptLimit = Math.ceil(ftCount * (constraints.partTimeCap / 100));

    return {
      maxVol,
      maxDay,
      maxBlock,
      ptLimit,
      requiredHeadsAtPeak: Math.ceil(maxVol / (constraints.avgProductivity * 4 * (constraints.targetUtilization / 100)))
    };
  }, [demand, solution, constraints]);

  const heatmapData = useMemo(() => {
    const supply: Record<string, Record<string, number>> = {};
    days.forEach(d => {
      supply[d] = {};
      TIME_BLOCKS.forEach(b => supply[d][b] = 0);
    });

    solution.roster.forEach(associate => {
      days.forEach(day => {
        const scheduleStr = associate.schedule[day];
        if (scheduleStr === 'OFF') return;

        const startHour = parseInt(scheduleStr.split(':')[0]);
        // Map 24h hour to 4h block for visualization
        let blockIndex = Math.floor(((startHour + 24 - 6) % 24) / 4);

        if (blockIndex >= 0 && blockIndex < 6) {
          const blocksOccupied = associate.role === 'Part Time' ? 1 : 2;
          for (let i = 0; i < blocksOccupied; i++) {
             const actualBlockIdx = (blockIndex + i) % 6;
             supply[day][TIME_BLOCKS[actualBlockIdx]] += 1;
          }
        }
      });
    });

    const data: Record<string, Record<string, { percent: number; reqHours: number; availHours: number }>> = {};
    days.forEach((day, dayIdx) => {
      data[day] = {};
      const dayDemand = demand[dayIdx];
      TIME_BLOCKS.forEach(block => {
        const volume = dayDemand.blocks[block];
        const heads = supply[day][block];
        const reqHours = constraints.avgProductivity > 0 ? volume / constraints.avgProductivity : 0;
        const availHours = heads * 4; 
        let percent = 0;
        if (reqHours === 0) percent = 0;
        else if (availHours === 0) percent = 999;
        else percent = Math.round((reqHours / availHours) * 100);
        data[day][block] = { percent, reqHours, availHours };
      });
    });
    return data;
  }, [solution, demand, constraints]);

  const getHeatmapColor = (util: number) => {
    if (util === 999) return 'bg-red-600 text-white';
    if (util > 110) return 'bg-red-500 text-white';
    if (util >= 85) return 'bg-emerald-500 text-white';
    if (util >= 70) return 'bg-blue-400 text-white';
    if (util > 0) return 'bg-blue-200 text-slate-700';
    return 'bg-slate-100 text-slate-400';
  };

  const totalWeeklyHours = solution.roster.reduce((acc, r) => acc + r.totalHours, 0);
  const requiredHours = solution.weeklyStats.totalVolume / constraints.avgProductivity;

  return (
    <div className="space-y-6 animate-in fade-in duration-700">

      <div className="flex items-center justify-between border-b border-slate-200 pb-4">
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => setView('overview')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'overview' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Overview
          </button>
          <button
            onClick={() => setView('heatmap')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'heatmap' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Heatmap
          </button>
          <button
            onClick={() => setView('roster')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'roster' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Roster
          </button>
          <button
            onClick={() => setView('explanation')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${
              view === 'explanation' ? 'bg-amber-100 text-amber-700' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            Logic
          </button>
          {isFrugal && (
            <button
              onClick={() => setView('frugal')}
              className={`px-4 py-2 rounded-lg text-sm font-bold transition-colors flex items-center gap-2 ${
                view === 'frugal' ? 'bg-amber-600 text-white shadow-lg' : 'bg-amber-100 text-amber-700'
              }`}
            >
              <Coins className="w-4 h-4" />
              Frugal Analysis
            </button>
          )}
        </div>
        <div className="hidden md:flex items-center gap-3">
           {isFrugal ? (
               <span className="px-3 py-1 rounded-full bg-amber-600 text-white text-[10px] font-bold tracking-widest flex items-center gap-1 shadow-sm uppercase">
                  <Coins className="w-3 h-3" /> Frugal MIP Enabled
               </span>
           ) : isOrTools ? (
               <span className="px-3 py-1 rounded-full bg-purple-100 text-purple-700 text-[10px] font-bold tracking-widest flex items-center gap-1 border border-purple-200 uppercase">
                  <Sparkles className="w-3 h-3" /> Pattern Solver
               </span>
           ) : null}
        </div>
      </div>

      {view === 'overview' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-100' : ''}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className={`p-2 rounded-lg ${isFrugal ? 'bg-amber-50' : 'bg-blue-50'}`}>
                  <Users className={`w-5 h-5 ${isFrugal ? 'text-amber-600' : 'text-blue-600'}`} />
                </div>
                <span className="text-sm font-medium text-slate-600">Total Hours</span>
              </div>
              <div className="text-2xl font-bold text-slate-900">
                {totalWeeklyHours.toLocaleString()} <span className="text-sm font-normal text-slate-400">hrs/wk</span>
              </div>
            </div>
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-100' : ''}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className={`p-2 rounded-lg ${isFrugal ? 'bg-emerald-50' : 'bg-emerald-50'}`}>
                  <TrendUp className="w-5 h-5 text-emerald-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Efficiency</span>
              </div>
              <div className="text-2xl font-bold text-slate-900">
                {solution.weeklyStats.blendedUtilization.toFixed(1)}% <span className="text-sm font-normal text-slate-400">utilization</span>
              </div>
            </div>
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-100' : ''}`}>
               <div className="flex items-center gap-3 mb-2">
                <div className={`p-2 rounded-lg ${isFrugal ? 'bg-amber-50' : 'bg-amber-50'}`}>
