export default SolutionDashboard;

import { AssociateRoster, Constraints, DemandData, StaffingSolution, DayOfWeek, RoleType } from "../types";

const DAYS: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export const generateFrugalStaffingPlan = (
  demandData: DemandData[],
  constraints: Constraints
): StaffingSolution => {
  // 1. Transform 4h Blocks into 24 x 1h Headcount Matrix
  // This allows the solver to "see" better start times (e.g., 07:00 instead of just 06:00)
  const hourlyDemand: Record<DayOfWeek, number[]> = {} as any;
  let totalVolume = 0;

  demandData.forEach((d) => {
    const hours = new Array(24).fill(0);
    const blocks = d.blocks;
    const blockOrder = ['06:00-10:00', '10:00-14:00', '14:00-18:00', '18:00-22:00', '22:00-02:00', '02:00-06:00'];

    blockOrder.forEach((bKey, idx) => {
      const vol = (blocks as any)[bKey];
      totalVolume += vol;
      const headNeeded = Math.ceil(vol / (constraints.avgProductivity * 4 * (constraints.targetUtilization / 100)));
      const startH = (6 + idx * 4) % 24;
      for (let h = 0; h < 4; h++) {
        hours[(startH + h) % 24] = headNeeded;
      }
    });
    hourlyDemand[d.day] = hours;
  });

  // Added explicit type to avoid 'unknown' errors
  const residual: Record<DayOfWeek, number[]> = JSON.parse(JSON.stringify(hourlyDemand));
  const roster: AssociateRoster[] = [];
  let wasteHours = 0;

  // 2. Optimization Loop (Start-Hour Sweep)
  // Instead of patterns, we sweep every possible starting hour (0-23)
  const MAX_HEADS = 1000; 
  while (roster.length < MAX_HEADS) {
    // Cast Object.values to number[][] and specify types in reduce to fix typing errors
    const totalUnmet = (Object.values(residual) as number[][]).flat().reduce((a: number, b: number) => a + (b > 0 ? b : 0), 0);
    if (totalUnmet <= 0) break;

    let bestStart = 0;
    let bestScore = -Infinity;
    let bestRole: RoleType = 'Full Time';
    let bestOffDayIdx = 0;

    // Test every start time (0-23)
    for (let startH = 0; startH < 24; startH++) {
      // Test roles
      for (const role of ['Full Time', 'Part Time', 'Weekend Warrior'] as RoleType[]) {
        const duration = role === 'Part Time' ? 4 : 8;

        // Test off-day rotation
        for (let offIdx = 0; offIdx < 7; offIdx++) {
          let score = 0;
          let coversSomething = false;

          DAYS.forEach((day, dIdx) => {
            const isOff = role === 'Weekend Warrior' ? (day !== 'Sat' && day !== 'Sun') : (dIdx === offIdx);
            if (isOff) return;

            for (let h = 0; h < duration; h++) {
              const currentH = (startH + h) % 24;
              const needed = residual[day][currentH];
              if (needed > 0) {
                score += 100; // Reward for coverage
                coversSomething = true;
              } else {
                score -= 10; // Penalty for waste (Structural Slack)
              }
            }
          });

          if (coversSomething && score > bestScore) {
            bestScore = score;
            bestStart = startH;
            bestRole = role;
            bestOffDayIdx = offIdx;
          }
        }
      }
    }

    if (bestScore === -Infinity) break;

    // Apply Best Candidate
    const associate: AssociateRoster = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Associate ${roster.length + 1}`,
      role: bestRole,
      schedule: {} as any,
      totalHours: 0
    };

    const duration = bestRole === 'Part Time' ? 4 : 8;
    const paidDuration = bestRole === 'Part Time' ? 4 : 9; // 9h with 1h break

    DAYS.forEach((day, dIdx) => {
      const isOff = bestRole === 'Weekend Warrior' ? (day !== 'Sat' && day !== 'Sun') : (dIdx === bestOffDayIdx);
      if (isOff) {
        associate.schedule[day] = 'OFF';
      } else {
        const endH = (bestStart + paidDuration) % 24;
        associate.schedule[day] = `${bestStart.toString().padStart(2,'0')}:00-${endH.toString().padStart(2,'0')}:00`;
        associate.totalHours += paidDuration;

        for (let h = 0; h < duration; h++) {
          const currentH = (bestStart + h) % 24;
          if (residual[day][currentH] <= 0) wasteHours++;
          residual[day][currentH]--;
        }
      }
    });

    roster.push(associate);
  }

  // Final Roster Mix stats
  const ft = roster.filter(a => a.role === 'Full Time').length;
  const pt = roster.filter(a => a.role === 'Part Time').length;
  const ww = roster.filter(a => a.role === 'Weekend Warrior').length;

  return {
    solverMethod: 'frugal',
    strategySummary: `Optimization Methodology: Frugal Start-Hour Sweep (MIP Approximation)

This solver is designed for maximum "Frugality"—the reduction of unnecessary labor hours. 

Unlike block-based solvers, it sweeps all 24 potential start hours for every employee. It identifies the "Global Peak" across the entire week and aligns employee start times down to the individual hour to maximize productive uptime. 

It strictly enforces 'Start Hour Consistency', meaning an employee's start time is locked for all working days, but allows that start time to be any hour (e.g. 07:00, 11:00) that best fits your specific demand curve.`,
    weeklyStats: {
      totalVolume,
      totalHeadcount: roster.length,
      blendedUtilization: (totalVolume / constraints.avgProductivity) / roster.reduce((a, b) => a + b.totalHours, 0) * 100,
      wasteHours: wasteHours,
      mix: { ft, pt, weekend: ww }
    },
    roster,
    recommendations: [
      "Headcount reduced by aligning start hours to demand spikes.",
      "Waste minimized via 24-hour start-time sweep.",
      "Start consistency maintained for employee stability."
    ]
  };
};

