import React, { useState, useMemo } from 'react';
import { StaffingSolution, DemandData, Constraints, TIME_BLOCKS, DayOfWeek } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { 
  CheckCircle2, Users, Clock, CalendarDays, BarChart2, 
  Activity, TrendingUp, TrendingDown, Sparkles, BookOpen, 
  ChevronRight, Target, Workflow, Scale, Info, Lightbulb,
  Zap, ShieldAlert
} from 'lucide-react';

interface SolutionDashboardProps {
  solution: StaffingSolution;
  demand: DemandData[];
  constraints: Constraints;
}

const SolutionDashboard: React.FC<SolutionDashboardProps> = ({ solution, demand, constraints }) => {
  const [view, setView] = useState<'overview' | 'roster' | 'heatmap' | 'explanation' | 'frugal'>('overview');

  const solverMode = solution.solverMethod;
  const isOrTools = solverMode === 'ortools';
  const isFrugal = solverMode === 'frugal';

  const themeColor = isFrugal ? 'text-amber-600' : isOrTools ? 'text-purple-600' : 'text-indigo-600';
  const themeBg = isFrugal ? 'bg-amber-50' : isOrTools ? 'bg-purple-50' : 'bg-indigo-50';
  const themeButton = isFrugal ? 'bg-amber-100 text-amber-700' : isOrTools ? 'bg-purple-100 text-purple-700' : 'bg-indigo-100 text-indigo-700';

  const mixData = [
    { name: 'Full Time', value: solution.weeklyStats.mix.ft, color: isFrugal ? '#d97706' : isOrTools ? '#9333ea' : '#3b82f6' },
    { name: 'Part Time', value: solution.weeklyStats.mix.pt, color: '#10b981' },
    { name: 'Weekend Only', value: solution.weeklyStats.mix.weekend, color: '#f59e0b' },
  ].filter(d => d.value > 0);

  const days: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  const simulationFacts = useMemo(() => {
    let maxVol = 0;
    let maxDay = 'Mon';
    let maxBlock = '06:00-10:00';

    demand.forEach(d => {
      Object.entries(d.blocks).forEach(([block, vol]) => {
        if (vol > maxVol) {
          maxVol = vol;
          maxDay = d.day;
          maxBlock = block;
        }
      });
    });

    const ftCount = solution.weeklyStats.mix.ft;
    const ptLimit = Math.ceil(ftCount * (constraints.partTimeCap / 100));

    return {
      maxVol,
      maxDay,
      maxBlock,
      ptLimit,
      requiredHeadsAtPeak: Math.ceil(maxVol / (constraints.avgProductivity * 4 * (constraints.targetUtilization / 100)))
    };
  }, [demand, solution, constraints]);

  const heatmapData = useMemo(() => {
    const supply: Record<string, Record<string, number>> = {};
    days.forEach(d => {
      supply[d] = {};
      TIME_BLOCKS.forEach(b => supply[d][b] = 0);
    });

    solution.roster.forEach(associate => {
      days.forEach(day => {
        const scheduleStr = associate.schedule[day];
        if (scheduleStr === 'OFF') return;

        const startHour = parseInt(scheduleStr.split(':')[0]);
        // Handle custom start times from Frugal solver
        let blockIndex = Math.floor(((startHour + 24 - 6) % 24) / 4);

        if (blockIndex >= 0 && blockIndex < 6) {
          const blocksOccupied = associate.role === 'Part Time' ? 1 : 2;
          for (let i = 0; i < blocksOccupied; i++) {
             const actualBlockIdx = (blockIndex + i) % 6;
             supply[day][TIME_BLOCKS[actualBlockIdx]] += 1;
          }
        }
      });
    });

    const data: Record<string, Record<string, { percent: number; reqHours: number; availHours: number }>> = {};
    days.forEach((day, dayIdx) => {
      data[day] = {};
      const dayDemand = demand[dayIdx];
      TIME_BLOCKS.forEach(block => {
        const volume = dayDemand.blocks[block];
        const heads = supply[day][block];
        const reqHours = constraints.avgProductivity > 0 ? volume / constraints.avgProductivity : 0;
        const availHours = heads * 4; 
        let percent = 0;
        if (reqHours === 0) percent = 0;
        else if (availHours === 0) percent = 999;
        else percent = Math.round((reqHours / availHours) * 100);
        data[day][block] = { percent, reqHours, availHours };
      });
    });
    return data;
  }, [solution, demand, constraints]);

  const getHeatmapColor = (util: number) => {
    if (util === 999) return 'bg-red-600 text-white';
    if (util > 110) return 'bg-red-500 text-white';
    if (util >= 85) return 'bg-emerald-500 text-white';
    if (util >= 70) return 'bg-blue-400 text-white';
    if (util > 0) return 'bg-blue-200 text-slate-700';
    return 'bg-slate-100 text-slate-400';
  };

  const totalWeeklyHours = solution.roster.reduce((acc, r) => acc + r.totalHours, 0);
  const requiredHours = solution.weeklyStats.totalVolume / constraints.avgProductivity;

  return (
    <div className="space-y-6 animate-in fade-in duration-700">

      <div className="flex items-center justify-between border-b border-slate-200 pb-4">
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => setView('overview')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors ${
              view === 'overview' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Overview
          </button>
          <button
            onClick={() => setView('heatmap')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors ${
              view === 'heatmap' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Heatmap
          </button>
          <button
            onClick={() => setView('roster')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors ${
              view === 'roster' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Detailed Roster
          </button>
          {isFrugal && (
            <button
              onClick={() => setView('frugal')}
              className={`px-4 py-2 rounded-lg text-sm font-black transition-colors flex items-center gap-2 ${
                view === 'frugal' ? 'bg-amber-600 text-white' : 'text-amber-600 hover:bg-amber-50 border border-amber-200'
              }`}
            >
              <Zap className="w-4 h-4" />
              Frugal Analysis
            </button>
          )}
          <button
            onClick={() => setView('explanation')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors flex items-center gap-2 ${
              view === 'explanation' ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            Logic
          </button>
        </div>
        <div className="hidden md:flex items-center gap-3">
           <span className="px-3 py-1 rounded-full bg-slate-100 text-slate-700 text-[10px] font-black tracking-widest flex items-center gap-1 border border-slate-200 uppercase">
              <Sparkles className="w-3 h-3" /> Solver Verified
           </span>
        </div>
      </div>

      {view === 'overview' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-200' : ''}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className={`p-2 rounded-lg ${themeBg}`}>
                  <Users className={`w-5 h-5 ${themeColor}`} />
                </div>
                <span className="text-sm font-black text-slate-500 uppercase tracking-tighter">Weekly Hours</span>
              </div>
              <div className="text-2xl font-black text-slate-900">
                {totalWeeklyHours.toLocaleString()} <span className="text-sm font-normal text-slate-400">hrs</span>
              </div>
            </div>
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-200' : ''}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-emerald-50 rounded-lg">
                  <Clock className="w-5 h-5 text-emerald-600" />
                </div>
                <span className="text-sm font-black text-slate-500 uppercase tracking-tighter">Efficiency</span>
              </div>
              <div className="text-2xl font-black text-slate-900">
                {solution.weeklyStats.blendedUtilization.toFixed(1)}% <span className="text-sm font-normal text-slate-400">util.</span>
              </div>
            </div>
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-200' : ''}`}>
               <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-slate-50 rounded-lg">
                  <CalendarDays className="w-5 h-5 text-slate-600" />
                </div>
                <span className="text-sm font-black text-slate-500 uppercase tracking-tighter">Headcount Mix</span>
              </div>
              <div className="text-sm text-slate-700 mt-1 font-bold">
                {solution.weeklyStats.mix.ft} FT, {solution.weeklyStats.mix.pt} PT, {solution.weeklyStats.mix.weekend} WW
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className={`text-lg font-black mb-3 ${themeColor} uppercase tracking-tight`}>Solver Strategy Breakdown</h3>
              <p className="text-slate-600 leading-relaxed text-sm whitespace-pre-wrap font-medium">{solution.strategySummary}</p>
              <h4 className="font-black text-slate-800 mt-6 mb-3 uppercase tracking-widest text-[10px]">Optimization Results</h4>
              <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {solution.recommendations.map((rec, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-xs text-slate-600 bg-slate-50 p-2.5 rounded-lg border border-slate-100 font-medium">
                    <CheckCircle2 className={`w-3.5 h-3.5 mt-0.5 flex-shrink-0 ${themeColor}`} />
                    {rec}
                  </li>
                ))}
              </ul>
            </div>
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center justify-center">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 w-full text-center">Staffing Distribution</h3>
              <div className="w-full h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={mixData}
                      cx="50%"
                      cy="45%"
                      innerRadius={50}
                      outerRadius={80}
