                      dataKey="value"
                    >
                      {mixData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" height={36} iconSize={10} wrapperStyle={{ fontSize: '10px', fontWeight: 'bold', paddingTop: '10px' }}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>
      )}

      {view === 'heatmap' && (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex flex-col gap-4 mb-6">
             <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                   <BarChart2 className={`w-5 h-5 ${themeColor}`} />
                   <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">Coverage Heatmap</h3>
                </div>
                <div className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em]">
                    Unit: % Utilization Target
                </div>
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-[10px] text-left border-collapse">
              <thead>
                <tr>
                  <th className="p-3 bg-slate-50 border border-slate-200 text-slate-500 font-black uppercase tracking-widest">Day</th>
                  {TIME_BLOCKS.map(block => (
                    <th key={block} className="p-3 bg-slate-50 border border-slate-200 text-center text-slate-500 font-black uppercase min-w-[120px]">
                      {block}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {days.map(day => (
                  <tr key={day}>
                    <td className="p-3 border border-slate-200 font-black text-slate-700 bg-slate-50 uppercase">{day}</td>
                    {TIME_BLOCKS.map(block => {
                      const { percent, reqHours, availHours } = heatmapData[day][block];
                      return (
                        <td key={`${day}-${block}`} className={`p-2 border border-white text-center transition-colors ${getHeatmapColor(percent)}`}>
                           <div className="flex flex-col items-center justify-center h-12">
                                <span className="font-black text-sm">{percent === 999 ? 'GAP' : `${percent}%`}</span>
                                <span className="opacity-70 font-bold tracking-tighter">({availHours}h avail)</span>
                           </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'frugal' && isFrugal && (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
