import { AssociateRoster, Constraints, DemandData, StaffingSolution, DayOfWeek, RoleType, TimeBlock } from "../types";

const DAYS: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export const generateFrugalStaffingPlan = (
  demandData: DemandData[],
  constraints: Constraints
): StaffingSolution => {
  // 1. Convert 4h blocks into a 24-hour demand matrix (1h resolution)
  const hourlyDemand: Record<DayOfWeek, number[]> = {
    'Mon': [], 'Tue': [], 'Wed': [], 'Thu': [], 'Fri': [], 'Sat': [], 'Sun': []
  };
  let totalVolume = 0;

  demandData.forEach((d) => {
    const hours = new Array(24).fill(0);
    const blocks = d.blocks;
    const blockOrder: TimeBlock[] = ['06:00-10:00', '10:00-14:00', '14:00-18:00', '18:00-22:00', '22:00-02:00', '02:00-06:00'];

    blockOrder.forEach((bKey, idx) => {
      const vol = blocks[bKey];
      totalVolume += vol;
      const headNeeded = Math.ceil(vol / (constraints.avgProductivity * 4 * (constraints.targetUtilization / 100)));
      const startH = (6 + idx * 4) % 24;
      for (let h = 0; h < 4; h++) {
        hours[(startH + h) % 24] = headNeeded;
      }
    });
    hourlyDemand[d.day] = hours;
  });

  const residual: Record<DayOfWeek, number[]> = JSON.parse(JSON.stringify(hourlyDemand));
  const roster: AssociateRoster[] = [];
  let wasteHours = 0;

  // 2. Optimization Loop (Iterative Candidate Selection)
  // We sweep every possible start hour (0-23) for different roles and off-days
  const MAX_ASSOCIATES = 500; 
  while (roster.length < MAX_ASSOCIATES) {
    const values = Object.values(residual) as number[][];
    const totalUnmet: number = values.flat().reduce((acc: number, val: number) => acc + (val > 0 ? val : 0), 0);
    if (totalUnmet <= 0) break;

    let bestStart = 0;
    let bestScore = -Infinity;
    let bestRole: RoleType = 'Full Time';
    let bestOffDayIdx = 0;

    // Test every start time (0-23)
    for (let startH = 0; startH < 24; startH++) {
      const roles: RoleType[] = ['Full Time', 'Part Time', 'Weekend Warrior'];
      for (const role of roles) {
        // Full Time works 8h (spread over 9h with break), PT works 4h
        const workDuration = role === 'Part Time' ? 4 : 8;

        for (let offIdx = 0; offIdx < 7; offIdx++) {
          let score = 0;
          let covered = 0;

          DAYS.forEach((day, dIdx) => {
            const isOff = role === 'Weekend Warrior' ? (day !== 'Sat' && day !== 'Sun') : (dIdx === offIdx);
            if (isOff) return;

            // Check coverage for the shift duration
            for (let h = 0; h < workDuration; h++) {
              const currentH = (startH + h) % 24;
              const needed = residual[day][currentH];
              if (needed > 0) {
                score += 100; // High reward for filling a gap
                covered++;
              } else {
                score -= 15; // Penalty for overlap waste (slack)
              }
            }
          });

          // Weighting: Prefer FT for stability, but PT for isolated spikes
          if (role === 'Full Time') score += 10;
          if (role === 'Weekend Warrior') score += 5;

          if (covered > 0 && score > bestScore) {
            bestScore = score;
            bestStart = startH;
            bestRole = role;
            bestOffDayIdx = offIdx;
          }
        }
      }
    }

    if (bestScore === -Infinity) break;

    // Build the associate based on the best pattern found
    const associate: AssociateRoster = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Associate ${roster.length + 1}`,
      role: bestRole,
      schedule: { 'Mon': 'OFF', 'Tue': 'OFF', 'Wed': 'OFF', 'Thu': 'OFF', 'Fri': 'OFF', 'Sat': 'OFF', 'Sun': 'OFF' },
      totalHours: 0
    };

    const workDuration = bestRole === 'Part Time' ? 4 : 8;
    const shiftWithBreak = bestRole === 'Part Time' ? 4 : 9; // 9h including 1h rotational break

    DAYS.forEach((day, dIdx) => {
      const isOff = bestRole === 'Weekend Warrior' ? (day !== 'Sat' && day !== 'Sun') : (dIdx === bestOffDayIdx);
      if (!isOff) {
        const endH = (bestStart + shiftWithBreak) % 24;
        associate.schedule[day] = `${bestStart.toString().padStart(2, '0')}:00-${endH.toString().padStart(2, '0')}:00`;
        associate.totalHours += shiftWithBreak;

        // Deduct from residual demand (we only deduct the work duration blocks)
        for (let h = 0; h < workDuration; h++) {
          const currentH = (bestStart + h) % 24;
          if (residual[day][currentH] <= 0) wasteHours++;
          residual[day][currentH]--;
        }
      }
    });

    roster.push(associate);
  }

  const ft = roster.filter(a => a.role === 'Full Time').length;
  const pt = roster.filter(a => a.role === 'Part Time').length;
  const ww = roster.filter(a => a.role === 'Weekend Warrior').length;
  const totalHours = roster.reduce((s, a) => s + a.totalHours, 0);

  return {
    solverMethod: 'frugal',
    strategySummary: `Optimization Method: Frugal Start-Hour Sweep (ILP Approximation)

This solver is optimized to minimize "Overlap Waste," specifically identifying start times that prevent unnecessary staffing during shift transitions (e.g., the 13:00-14:00 overlap).

1.  **Global Sweep:** Evaluates all 24 potential start hours for every employee, allowing for unconventional but efficient shifts (like 07:00-16:00 or 11:00-20:00).
2.  **Start-Time Consistency:** Ensures each employee maintains a single, fixed start time throughout their work week, as per operational stability requirements.
3.  **Slack Reduction:** Explicitly penalizes over-coverage, forcing the algorithm to find "lean" start times that match the curvature of your demand graph.`,
    weeklyStats: {
      totalVolume,
      totalHeadcount: roster.length,
      blendedUtilization: totalHours > 0 ? (totalVolume / constraints.avgProductivity) / totalHours * 100 : 0,
      wasteHours: wasteHours,
      mix: { ft, pt, weekend: ww }
    },
    roster,
    recommendations: [
      "Frugal sweep reduced overlap waste during shift handovers.",
      "Start times aligned to the hourly demand curve rather than fixed 4h blocks.",
      "Maintained weekly start-time consistency for all associates."
    ]
  };
};

