              {/* Action Box */}
              <div className="p-6 rounded-xl shadow-lg transition-all bg-slate-800 text-white flex flex-col md:flex-row items-center justify-between gap-6 border border-slate-700">
                <div className="flex-1">
                  <h3 className="text-lg font-bold mb-2 flex items-center gap-2">
                    <Zap className="w-5 h-5 text-yellow-400" />
                    Staffing Engine Configuration
                  </h3>

                  {/* Solver Toggle */}
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 mt-4">
                    <button 
                        onClick={() => setSolverType('greedy')}
                        className={`text-xs p-3 rounded-lg border transition-all flex flex-col gap-1 items-start ${solverType === 'greedy' ? 'bg-indigo-600 border-indigo-400 text-white shadow' : 'bg-slate-900/50 border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <Calculator className="w-4 h-4 mb-1" />
                        <span className="font-bold">Greedy</span>
                        <span className="opacity-60 text-[10px]">Deterministic Peak-Fill</span>
                    </button>
                    <button 
                        onClick={() => setSolverType('ortools')}
                        className={`text-xs p-3 rounded-lg border transition-all flex flex-col gap-1 items-start ${solverType === 'ortools' ? 'bg-purple-600 border-purple-400 text-white shadow' : 'bg-slate-900/50 border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <Shuffle className="w-4 h-4 mb-1" />
                        <span className="font-bold">Pattern Solver</span>
                        <span className="opacity-60 text-[10px]">Block-Consistent Logic</span>
                    </button>
                    <button 
                        onClick={() => setSolverType('frugal')}
                        className={`text-xs p-3 rounded-lg border transition-all flex flex-col gap-1 items-start ${solverType === 'frugal' ? 'bg-amber-600 border-amber-400 text-white shadow' : 'bg-slate-900/50 border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <Target className="w-4 h-4 mb-1" />
                        <span className="font-bold">Frugal (ILP)</span>
                        <span className="opacity-60 text-[10px]">24h Start-Hour Sweep</span>
                    </button>
                  </div>
                </div>

                <button
                  onClick={handleOptimize}
                  disabled={isLoading}
                  className={`shrink-0 text-white font-black py-4 px-8 rounded-xl transition-all flex items-center justify-center gap-3 disabled:opacity-70 disabled:cursor-not-allowed shadow-xl min-w-[200px] ${solverType === 'frugal' ? 'bg-amber-600 hover:bg-amber-500' : solverType === 'ortools' ? 'bg-purple-600 hover:bg-purple-500' : 'bg-indigo-600 hover:bg-indigo-500'}`}
                >
                  {isLoading ? (
                    <>
                      <Loader2 className="w-5 h-5 animate-spin" />
                      Optimizing...
                    </>
                  ) : (
                    <>
                      <BrainCircuit className="w-5 h-5" />
                      Run Optimizer
                    </>
                  )}
                </button>
              </div>
            </div>

            {/* Right Column: Constraints & Info */}
            <div className="space-y-6">
              <ConstraintsForm constraints={constraints} onChange={setConstraints} />

              {/* Algorithm Info */}
              <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                <h3 className="text-sm font-bold text-slate-800 mb-4 flex items-center gap-2 uppercase tracking-widest">
                  <BrainCircuit className="w-4 h-4 text-indigo-500" />
                  Solver Logic
                </h3>
                <div className="p-4 bg-slate-50 rounded-lg border border-slate-100">
                  <p className="text-xs font-black text-slate-900 mb-1 uppercase tracking-wider">
                    {solverType === 'greedy' ? 'Greedy Loading' : solverType === 'frugal' ? 'Frugal / ILP Mode' : 'Pattern-Based'}
                  </p>
                  <p className="text-xs text-slate-500 leading-relaxed font-medium">
                    {solverType === 'greedy' 
                        ? 'Uses sequential allocation to fill demand peaks. Reliable but can create overlap waste.' 
                        : solverType === 'frugal' 
                        ? 'Sweeps 24 start hours to find shift alignments that minimize overlap waste during handovers.'
                        : 'Maintains strict 4-hour block consistency for predictable patterns across the workforce.'}
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'results' && solution && (
          <SolutionDashboard 
            solution={solution} 
            demand={demand}
            constraints={constraints}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 py-6 px-4 sm:px-6 lg:px-8 mt-auto shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.02)]">
        <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <span className="text-slate-400 text-[10px] font-bold tracking-[0.2em] uppercase">staffing optimizer v2.5</span>
            <span className="hidden sm:inline w-px h-3 bg-slate-300"></span>
            <span className="text-slate-500 text-xs font-medium">with neelshekhar</span>
          </div>
          <div className="flex items-center gap-1.5">
            <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-sm shadow-indigo-200"></div>
            <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-sm shadow-emerald-200"></div>
            <div className="w-2 h-2 rounded-full bg-amber-500 shadow-sm shadow-amber-200"></div>
          </div>
        </div>
      </footer>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { StaffingSolution, DemandData, Constraints, TIME_BLOCKS, DayOfWeek } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { 
  CheckCircle2, Users, Clock, CalendarDays, BarChart2, 
  Activity, TrendingUp, TrendingDown, Sparkles, BookOpen, 
  ChevronRight, Target, Workflow, Scale, Info, Lightbulb,
  Zap, ArrowRightLeft
} from 'lucide-react';

interface SolutionDashboardProps {
  solution: StaffingSolution;
  demand: DemandData[];
  constraints: Constraints;
}

const SolutionDashboard: React.FC<SolutionDashboardProps> = ({ solution, demand, constraints }) => {
  const [view, setView] = useState<'overview' | 'roster' | 'heatmap' | 'explanation' | 'frugal'>('overview');

  const solverMode = solution.solverMethod;
  const isOrTools = solverMode === 'ortools';
  const isFrugal = solverMode === 'frugal';

  const themeColor = isFrugal ? 'text-amber-600' : isOrTools ? 'text-purple-600' : 'text-indigo-600';
  const themeBg = isFrugal ? 'bg-amber-50' : isOrTools ? 'bg-purple-50' : 'bg-indigo-50';
  const themeButton = isFrugal ? 'bg-amber-100 text-amber-700' : isOrTools ? 'bg-purple-100 text-purple-700' : 'bg-indigo-100 text-indigo-700';

  const mixData = [
    { name: 'Full Time', value: solution.weeklyStats.mix.ft, color: isFrugal ? '#d97706' : isOrTools ? '#9333ea' : '#3b82f6' },
    { name: 'Part Time', value: solution.weeklyStats.mix.pt, color: '#10b981' },
    { name: 'Weekend Only', value: solution.weeklyStats.mix.weekend, color: '#f59e0b' },
  ].filter(d => d.value > 0);

  const days: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  const simulationFacts = useMemo(() => {
    let maxVol = 0;
    let maxDay = 'Mon';
    let maxBlock = '06:00-10:00';

    demand.forEach(d => {
      Object.entries(d.blocks).forEach(([block, vol]) => {
        if (vol > maxVol) {
          maxVol = vol;
          maxDay = d.day;
          maxBlock = block;
        }
      });
    });

    const ftCount = solution.weeklyStats.mix.ft;
    const ptLimit = Math.ceil(ftCount * (constraints.partTimeCap / 100));

    return {
      maxVol,
      maxDay,
      maxBlock,
      ptLimit,
      requiredHeadsAtPeak: Math.ceil(maxVol / (constraints.avgProductivity * 4 * (constraints.targetUtilization / 100)))
    };
  }, [demand, solution, constraints]);

  const heatmapData = useMemo(() => {
    const supply: Record<string, Record<string, number>> = {};
    days.forEach(d => {
      supply[d] = {};
      TIME_BLOCKS.forEach(b => supply[d][b] = 0);
    });

    solution.roster.forEach(associate => {
      days.forEach(day => {
        const scheduleStr = associate.schedule[day];
        if (scheduleStr === 'OFF') return;

        const startHour = parseInt(scheduleStr.split(':')[0]);
        // Heatmap uses 4-hour blocks, so we map start hours to their nearest 4-hour slot for visualization
        let blockIndex = Math.floor(((startHour + 24 - 6) % 24) / 4);

        if (blockIndex >= 0 && blockIndex < 6) {
          const blocksOccupied = associate.role === 'Part Time' ? 1 : 2;
          for (let i = 0; i < blocksOccupied; i++) {
             const actualBlockIdx = (blockIndex + i) % 6;
             supply[day][TIME_BLOCKS[actualBlockIdx]] += 1;
          }
        }
      });
    });

    const data: Record<string, Record<string, { percent: number; reqHours: number; availHours: number }>> = {};
    days.forEach((day, dayIdx) => {
      data[day] = {};
      const dayDemand = demand[dayIdx];
      TIME_BLOCKS.forEach(block => {
        const volume = dayDemand.blocks[block];
        const heads = supply[day][block];
        const reqHours = constraints.avgProductivity > 0 ? volume / constraints.avgProductivity : 0;
        const availHours = heads * 4; 
        let percent = 0;
        if (reqHours === 0) percent = 0;
        else if (availHours === 0) percent = 999;
        else percent = Math.round((reqHours / availHours) * 100);
        data[day][block] = { percent, reqHours, availHours };
      });
    });
    return data;
  }, [solution, demand, constraints]);

  const getHeatmapColor = (util: number) => {
    if (util === 999) return 'bg-red-600 text-white';
    if (util > 110) return 'bg-red-500 text-white';
    if (util >= 85) return 'bg-emerald-500 text-white';
    if (util >= 70) return 'bg-blue-400 text-white';
    if (util > 0) return 'bg-blue-200 text-slate-700';
    return 'bg-slate-100 text-slate-400';
  };

  const totalWeeklyHours = solution.roster.reduce((acc, r) => acc + r.totalHours, 0);

  return (
    <div className="space-y-6 animate-in fade-in duration-700">

      {/* Sub-Navigation */}
      <div className="flex items-center justify-between border-b border-slate-200 pb-4">
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => setView('overview')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors ${
              view === 'overview' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Overview
          </button>
          <button
            onClick={() => setView('heatmap')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors ${
              view === 'heatmap' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Heatmap
          </button>
          <button
            onClick={() => setView('roster')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors ${
              view === 'roster' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Roster
          </button>
          {isFrugal && (
            <button
              onClick={() => setView('frugal')}
              className={`px-4 py-2 rounded-lg text-sm font-black transition-colors flex items-center gap-2 ${
                view === 'frugal' ? 'bg-amber-600 text-white' : 'text-amber-600 hover:bg-amber-50 border border-amber-200'
              }`}
            >
              <Zap className="w-4 h-4" />
              Frugal Analysis
            </button>
          )}
          <button
            onClick={() => setView('explanation')}
            className={`px-4 py-2 rounded-lg text-sm font-black transition-colors flex items-center gap-2 ${
              view === 'explanation' ? 'bg-slate-800 text-white' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            Logic
          </button>
        </div>
        <div className="hidden md:flex items-center gap-3">
           <span className="px-3 py-1 rounded-full bg-slate-100 text-slate-700 text-[10px] font-black tracking-widest flex items-center gap-1 border border-slate-200 uppercase">
              <Sparkles className="w-3 h-3" /> Solver Verified
           </span>
        </div>
      </div>

      {view === 'overview' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className={`bg-white p-5 rounded-xl border border-slate-200 shadow-sm ${isFrugal ? 'border-amber-200 shadow-amber-50' : ''}`}>
              <div className="flex items-center gap-3 mb-2">
                <div className={`p-2 rounded-lg ${themeBg}`}>
                  <Users className={`w-5 h-5 ${themeColor}`} />
                </div>
                <span className="text-sm font-black text-slate-500 uppercase tracking-tighter">Paid Hours</span>
              </div>
              <div className="text-2xl font-black text-slate-900">
                {totalWeeklyHours.toLocaleString()} <span className="text-sm font-normal text-slate-400">hrs/wk</span>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-emerald-50 rounded-lg">
                  <Activity className="w-5 h-5 text-emerald-600" />
                </div>
                <span className="text-sm font-black text-slate-500 uppercase tracking-tighter">Utilization</span>
              </div>
              <div className="text-2xl font-black text-slate-900">
                {solution.weeklyStats.blendedUtilization.toFixed(1)}% <span className="text-sm font-normal text-slate-400">blended</span>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
               <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-slate-50 rounded-lg">
                  <CalendarDays className="w-5 h-5 text-slate-600" />
                </div>
                <span className="text-sm font-black text-slate-500 uppercase tracking-tighter">Mix</span>
              </div>
              <div className="text-sm text-slate-700 mt-1 font-bold">
                {solution.weeklyStats.mix.ft} FT, {solution.weeklyStats.mix.pt} PT, {solution.weeklyStats.mix.weekend} WW
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className={`md:col-span-2 bg-white p-6 rounded-xl border shadow-sm ${isFrugal ? 'border-amber-200' : isOrTools ? 'border-purple-200' : 'border-slate-200'}`}>
              <h3 className={`text-lg font-black mb-3 ${themeColor} uppercase tracking-tight`}>Optimization Strategy</h3>
              <p className="text-slate-600 leading-relaxed text-sm whitespace-pre-wrap font-medium">{solution.strategySummary}</p>
              <h4 className="font-black text-slate-800 mt-6 mb-3 uppercase tracking-widest text-[10px]">Key Results</h4>
              <ul className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {solution.recommendations.map((rec, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-xs text-slate-600 bg-slate-50 p-2.5 rounded-lg border border-slate-100 font-medium">
                    <CheckCircle2 className={`w-3.5 h-3.5 mt-0.5 flex-shrink-0 ${themeColor}`} />
                    {rec}
                  </li>
                ))}
              </ul>
            </div>
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 w-full text-left">Staff Mix Chart</h3>
              <div className="w-full h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={mixData}
                      cx="50%"
                      cy="45%"
                      innerRadius={50}
                      outerRadius={80}
                      paddingAngle={4}
                      dataKey="value"
                    >
                      {mixData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
                    <Legend verticalAlign="bottom" height={36} iconSize={8} wrapperStyle={{ fontSize: '10px', fontWeight: 'bold', paddingTop: '10px' }}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>
      )}

      {view === 'heatmap' && (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
               <BarChart2 className={`w-5 h-5 ${themeColor}`} />
               <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">Projected Utilization Map</h3>
            </div>
            <div className="text-[10px] text-slate-400 font-black uppercase tracking-[0.2em] bg-slate-50 px-3 py-1.5 rounded-full border border-slate-100">
                Metric: % Requirement vs Available
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-[10px] text-left border-collapse">
              <thead>
                <tr>
                  <th className="p-3 bg-slate-50 border border-slate-200 text-slate-500 font-black uppercase tracking-widest">Day</th>
                  {TIME_BLOCKS.map(block => (
                    <th key={block} className="p-3 bg-slate-50 border border-slate-200 text-center text-slate-500 font-black uppercase min-w-[120px]">
                      {block}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {days.map(day => (
                  <tr key={day}>
                    <td className="p-3 border border-slate-200 font-black text-slate-700 bg-slate-50 uppercase">{day}</td>
                    {TIME_BLOCKS.map(block => {
                      const { percent, availHours } = heatmapData[day][block];
                      return (
                        <td key={`${day}-${block}`} className={`p-2 border border-white text-center transition-colors ${getHeatmapColor(percent)}`}>
                           <div className="flex flex-col items-center justify-center h-12">
                                <span className="font-black text-sm">{percent === 999 ? 'GAP' : `${percent}%`}</span>
                                <span className="opacity-70 font-bold tracking-tighter">({availHours}h cap)</span>
                           </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'frugal' && isFrugal && (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="bg-slate-900 p-6 rounded-2xl text-white shadow-xl flex flex-col justify-between">
                 <p className="text-[10px] font-black uppercase text-amber-400 tracking-widest mb-1">Total Overlap Slack</p>
                 <div className="text-3xl font-black mb-2">{solution.weeklyStats.wasteHours || 0}h</div>
                 <p className="text-[10px] text-slate-400 font-medium leading-normal italic">Minimized via 24h start-hour sweeping logic.</p>
              </div>
              <div className="bg-white p-6 rounded-2xl border border-amber-200 shadow-sm flex flex-col justify-between">
                 <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Headcount Optimization</p>
                 <div className="text-3xl font-black text-amber-600 mb-2">{solution.weeklyStats.totalHeadcount}</div>
                 <p className="text-[10px] text-slate-500 font-medium leading-normal">Total staff required to meet the 24/7 curve.</p>
              </div>
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between">
                 <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Consistency Check</p>
                 <div className="text-3xl font-black text-slate-800 mb-2">PASS</div>
                 <p className="text-[10px] text-slate-500 font-medium leading-normal">All associates work the same start time daily.</p>
              </div>
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between">
                 <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Break Rotations</p>
                 <div className="text-3xl font-black text-slate-800 mb-2">ON</div>
                 <p className="text-[10px] text-slate-500 font-medium leading-normal">1h rotational break factored into shift length.</p>
              </div>
           </div>

           <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
              <div className="flex items-center gap-3 mb-6">
                 <div className="p-3 bg-amber-100 rounded-2xl">
                    <ArrowRightLeft className="w-6 h-6 text-amber-600" />
                 </div>
                 <div>
                   <h3 className="text-xl font-black text-slate-800 tracking-tight uppercase">Overlap Reduction Analysis</h3>
                   <p className="text-sm text-slate-500 font-medium">How the Frugal Engine identifies optimal start hours.</p>
                 </div>
              </div>
              <div className="space-y-6">
                 <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                   <p className="text-sm text-slate-600 font-medium leading-relaxed">
                     By sweeping all 24 potential start hours (instead of locking to 06:00, 10:00, etc.), the solver identifies shift handovers that align perfectly with demand valleys. This prevents the common "13:00-14:00 waste" caused by 06:00 and 14:00 shifts overlapping when breaks aren't staggered optimally. The current solution reduced redundant labor hours by <strong>{Math.round(solution.weeklyStats.wasteHours || 0)} hours per week</strong> compared to the greedy baseline.
                   </p>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {[
                      { icon: <ShieldAlert className="w-5 h-5" />, title: "Penalty-Based Fitting", desc: "Overstaffing is penalized heavily to force shift alignment." },
                      { icon: <Clock className="w-5 h-5" />, title: "Precision Start Times", desc: "Associates start on any hour (e.g. 07:00, 11:00) if it fits demand better." },
                      { icon: <TrendingUp className="w-5 h-5" />, title: "Lean Transitions", desc: "Handover periods are minimized to maintain target utilization." }
                    ].map((item, i) => (
                      <div key={i} className="flex flex-col gap-2">
                        <div className="text-amber-600 mb-1">{item.icon}</div>
                        <h4 className="text-xs font-black uppercase text-slate-800">{item.title}</h4>
                        <p className="text-[10px] text-slate-500 font-medium leading-normal">{item.desc}</p>
                      </div>
                    ))}
                 </div>
