              </div>
            </div>

            <div className="space-y-6">
              <ConstraintsForm constraints={constraints} onChange={setConstraints} />
            </div>
          </div>
        )}

        {activeTab === 'results' && solution && (
          <SolutionDashboard 
            solution={solution} 
            demand={demand}
            constraints={constraints}
          />
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-6 px-4 sm:px-6 lg:px-8 mt-auto shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.02)]">
        <div className="max-w-7xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <span className="text-slate-400 text-[10px] font-bold tracking-[0.2em] uppercase">staffing optimizer v3.0</span>
            <span className="hidden sm:inline w-px h-3 bg-slate-300"></span>
            <span className="text-slate-500 text-xs font-medium">Overlap-Free Scheduling</span>
          </div>
        </div>
      </footer>
    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { StaffingSolution, DemandData, Constraints, TIME_BLOCKS, DayOfWeek } from '../types';
import { 
  PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer 
} from 'recharts';
import { 
  CheckCircle2, Users, Clock, CalendarDays, BarChart2, 
  Activity, TrendingUp, TrendingDown, BookOpen, 
  ChevronRight, Target, Workflow, Scale, Info, Lightbulb
} from 'lucide-react';

interface SolutionDashboardProps {
  solution: StaffingSolution;
  demand: DemandData[];
  constraints: Constraints;
}

const SolutionDashboard: React.FC<SolutionDashboardProps> = ({ solution, demand, constraints }) => {
  const [view, setView] = useState<'overview' | 'roster' | 'heatmap' | 'explanation'>('overview');
  const themeColor = 'text-indigo-600';
  const themeBg = 'bg-indigo-50';
  const themeButton = 'bg-indigo-100 text-indigo-700';

  const mixData = [
    { name: 'Full Time', value: solution.weeklyStats.mix.ft, color: '#3b82f6' },
    { name: 'Part Time', value: solution.weeklyStats.mix.pt, color: '#10b981' },
    { name: 'Weekend Only', value: solution.weeklyStats.mix.weekend, color: '#f59e0b' },
  ].filter(d => d.value > 0);

  const days: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  const simulationFacts = useMemo(() => {
    let maxVol = 0;
    let maxDay = 'Mon';
    let maxBlock = '06:00-10:00';

    demand.forEach(d => {
      Object.entries(d.blocks).forEach(([block, vol]) => {
        if (vol > maxVol) {
          maxVol = vol;
          maxDay = d.day;
          maxBlock = block;
        }
      });
    });

    const ftCount = solution.weeklyStats.mix.ft;
    const ptLimit = Math.ceil(ftCount * (constraints.partTimeCap / 100));

    return {
      maxVol,
      maxDay,
      maxBlock,
      ptLimit,
      requiredHeadsAtPeak: Math.ceil(maxVol / (constraints.avgProductivity * 4 * (constraints.targetUtilization / 100)))
    };
  }, [demand, solution, constraints]);

  const heatmapData = useMemo(() => {
    const supply: Record<string, Record<string, number>> = {};
    days.forEach(d => {
      supply[d] = {};
      TIME_BLOCKS.forEach(b => supply[d][b] = 0);
    });

    solution.roster.forEach(associate => {
      days.forEach(day => {
        const scheduleStr = associate.schedule[day];
        if (scheduleStr === 'OFF') return;

        const startHour = parseInt(scheduleStr.split(':')[0]);
        let blockIndex = -1;
        // Map user custom start hours back to demand blocks for the heatmap
        if (startHour === 6) blockIndex = 0;
        else if (startHour === 10) blockIndex = 1;
        else if (startHour === 15) blockIndex = 2; // 14:00 block
        else if (startHour === 18) blockIndex = 3;
        else if (startHour === 23) blockIndex = 4; // 22:00 block
        else if (startHour === 2) blockIndex = 5;

        if (blockIndex >= 0 && blockIndex < 6) {
          supply[day][TIME_BLOCKS[blockIndex]] += 1;
          if (associate.role !== 'Part Time') {
             const nextBlockIndex = (blockIndex + 1) % 6;
             supply[day][TIME_BLOCKS[nextBlockIndex]] += 1;
          }
        }
      });
    });

    const data: Record<string, Record<string, { percent: number; reqHours: number; availHours: number }>> = {};
    days.forEach((day, dayIdx) => {
      data[day] = {};
      const dayDemand = demand[dayIdx];
      TIME_BLOCKS.forEach(block => {
        const volume = dayDemand.blocks[block];
        const heads = supply[day][block];
        const reqHours = constraints.avgProductivity > 0 ? volume / constraints.avgProductivity : 0;
        const availHours = heads * 4; 
        let percent = 0;
        if (reqHours === 0) percent = 0;
        else if (availHours === 0) percent = 999;
        else percent = Math.round((reqHours / availHours) * 100);
        data[day][block] = { percent, reqHours, availHours };
      });
    });
    return data;
  }, [solution, demand, constraints]);

  const getHeatmapColor = (util: number) => {
    if (util === 999) return 'bg-red-600 text-white';
    if (util > 110) return 'bg-red-500 text-white';
    if (util >= 85) return 'bg-emerald-500 text-white';
    if (util >= 70) return 'bg-blue-400 text-white';
    if (util > 0) return 'bg-blue-200 text-slate-700';
    return 'bg-slate-100 text-slate-400';
  };

  const totalWeeklyHours = solution.roster.reduce((acc, r) => acc + r.totalHours, 0);
  const requiredHours = solution.weeklyStats.totalVolume / constraints.avgProductivity;

  return (
    <div className="space-y-6 animate-in fade-in duration-700">
      <div className="flex items-center justify-between border-b border-slate-200 pb-4">
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => setView('overview')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'overview' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Overview
          </button>
          <button
            onClick={() => setView('heatmap')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'heatmap' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Utilization Map
          </button>
          <button
            onClick={() => setView('roster')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              view === 'roster' ? themeButton : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            Roster
          </button>
          <button
            onClick={() => setView('explanation')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2 ${
              view === 'explanation' ? 'bg-amber-100 text-amber-700' : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            Logic
          </button>
        </div>
        <div className="text-sm text-slate-500">
            Headcount: <strong>{solution.weeklyStats.totalHeadcount}</strong>
        </div>
      </div>

      {view === 'overview' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-blue-50 rounded-lg">
                  <Users className="w-5 h-5 text-blue-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Total Hours</span>
              </div>
              <div className="text-2xl font-bold text-slate-900">
                {totalWeeklyHours.toLocaleString()} <span className="text-sm font-normal text-slate-400">hrs/wk</span>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-emerald-50 rounded-lg">
                  <Clock className="w-5 h-5 text-emerald-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Efficiency</span>
              </div>
              <div className="text-2xl font-bold text-slate-900">
                {solution.weeklyStats.blendedUtilization.toFixed(1)}% <span className="text-sm font-normal text-slate-400">util.</span>
              </div>
            </div>
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
               <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-amber-50 rounded-lg">
                  <CalendarDays className="w-5 h-5 text-amber-600" />
                </div>
                <span className="text-sm font-medium text-slate-600">Staff Mix</span>
              </div>
              <div className="text-sm text-slate-700 mt-1">
                <strong>{solution.weeklyStats.mix.ft}</strong> FT, <strong>{solution.weeklyStats.mix.pt}</strong> PT, <strong>{solution.weeklyStats.mix.weekend}</strong> WW
              </div>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2 bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="text-lg font-semibold mb-3 text-slate-800">Strategy Summary</h3>
              <p className="text-slate-600 leading-relaxed text-sm whitespace-pre-wrap">{solution.strategySummary}</p>
              <h4 className="font-medium text-slate-800 mt-6 mb-3">Model Recommendations</h4>
              <ul className="space-y-2">
                {solution.recommendations.map((rec, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-sm text-slate-600">
                    <CheckCircle2 className="w-4 h-4 mt-0.5 flex-shrink-0 text-emerald-500" />
                    {rec}
                  </li>
                ))}
              </ul>
            </div>
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col items-center">
              <h3 className="text-sm font-semibold text-slate-800 mb-4 w-full text-left">Headcount Distribution</h3>
              <div className="w-full h-64">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={mixData}
                      cx="50%"
                      cy="45%"
                      innerRadius={50}
                      outerRadius={80}
                      paddingAngle={2}
                      dataKey="value"
                    >
                      {mixData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
                    <Legend verticalAlign="bottom" align="center" iconSize={10} wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>
        </div>
      )}

      {view === 'heatmap' && (
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex flex-col gap-4 mb-6">
             <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                   <BarChart2 className={`w-5 h-5 ${themeColor}`} />
                   <h3 className="text-lg font-semibold text-slate-800">Utilization Heatmap</h3>
                </div>
                <div className="text-xs text-slate-500 bg-slate-50 px-3 py-1.5 rounded-full border border-slate-100">
                    Metric: % Util (Needed / Available)
                </div>
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left border-collapse">
              <thead>
                <tr>
                  <th className="p-3 bg-slate-50 border border-slate-200 text-slate-500 font-medium">Day</th>
                  {TIME_BLOCKS.map(block => (
                    <th key={block} className="p-3 bg-slate-50 border border-slate-200 text-center text-slate-500 font-medium min-w-[120px]">
                      {block}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {days.map(day => (
                  <tr key={day}>
                    <td className="p-3 border border-slate-200 font-semibold text-slate-700 bg-slate-50">{day}</td>
                    {TIME_BLOCKS.map(block => {
                      const { percent, reqHours, availHours } = heatmapData[day][block];
                      return (
                        <td key={`${day}-${block}`} className={`p-2 border border-white text-center transition-colors ${getHeatmapColor(percent)}`}>
                           <div className="flex flex-col items-center justify-center h-full">
                                <span className="font-bold text-sm">{percent === 999 ? 'GAP' : `${percent}%`}</span>
                                <span className="text-[10px] opacity-80 whitespace-nowrap">({Math.round(reqHours)} / {availHours})</span>
                           </div>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'roster' && (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-xs text-left">
              <thead className="text-slate-500 font-medium border-b border-slate-200 bg-slate-50">
                <tr>
                  <th className="px-4 py-3 sticky left-0 z-20 bg-slate-50">Associate</th>
                  <th className="px-4 py-3 sticky left-[120px] z-20 bg-slate-50 border-r border-slate-200">Role</th>
                  {days.map(d => (
                    <th key={d} className="px-2 py-3 text-center min-w-[100px]">{d}</th>
                  ))}
                  <th className="px-4 py-3 text-right">Hrs</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {solution.roster.map((person) => (
                  <tr key={person.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-4 py-2 font-medium text-slate-800 sticky left-0 bg-white z-10 whitespace-nowrap">
                      {person.name}
                    </td>
                    <td className="px-4 py-2 sticky left-[120px] bg-white z-10 whitespace-nowrap border-r border-slate-50">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-medium ${
                        person.role === 'Full Time' ? 'bg-blue-100 text-blue-700' :
                        person.role === 'Part Time' ? 'bg-emerald-100 text-emerald-700' :
                        'bg-amber-100 text-amber-700'
                      }`}>
                        {person.role}
                      </span>
                    </td>
                    {days.map(d => (
                      <td key={d} className="px-2 py-2 text-center">
                        <div className={`py-1 px-1 rounded ${
                          person.schedule[d] === 'OFF' 
                            ? 'bg-slate-100 text-slate-400' 
                            : 'bg-indigo-50 text-indigo-700 font-medium'
                        }`}>
                          {person.schedule[d]}
                        </div>
                      </td>
                    ))}
                    <td className="px-4 py-2 text-right font-semibold text-slate-700">
                      {person.totalHours}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === 'explanation' && (
        <div className="animate-in slide-in-from-right-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-6">
              <div className="bg-amber-50 border border-amber-200 p-6 rounded-xl shadow-sm">
                <div className="flex items-center gap-3 mb-4">
                   <Workflow className="w-6 h-6 text-amber-600" />
                   <h3 className="text-xl font-bold text-amber-900">Optimization Logic</h3>
                </div>
                <p className="text-amber-800 text-sm leading-relaxed mb-4">
                  The model uses a greedy satisfaction algorithm to match demand with labor. To eliminate the 14:00-15:00 wastage, shift boundaries were adjusted so the afternoon shift starts exactly when the morning shift ends (15:00).
                </p>
                <div className="flex gap-4 flex-wrap">
                  <div className="text-xs font-semibold text-amber-700 bg-white/50 px-3 py-1.5 rounded-lg border border-amber-100">
                    Overlap-Free Transition
                  </div>
                  <div className="text-xs font-semibold text-amber-700 bg-white/50 px-3 py-1.5 rounded-lg border border-amber-100">
                    23:00 Night Shift Start
                  </div>
                  <div className="text-xs font-semibold text-amber-700 bg-white/50 px-3 py-1.5 rounded-lg border border-amber-100">
                    Flexible Break Rotation
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                {[
                  {
                    title: "Block Transformation",
                    desc: "Demand is ingested in 4hr blocks, but shift start times are offset to align with operational handovers (e.g. 15:00 start for the mid-day peak).",
                    icon: <BarChart2 className="w-5 h-5" />,
                    color: "bg-blue-100 text-blue-600"
                  },
                  {
                    title: "Shift Synthesis",
                    desc: "Deterministic logic connects blocks into 8h (FT) and 4h (PT) productive windows. Each FT shift includes a 1h flexible break handled rotationally.",
                    icon: <Clock className="w-5 h-5" />,
                    color: "bg-indigo-100 text-indigo-600"
                  },
                  {
                    title: "Mix Compliance",
                    desc: `The solver promotes associates to FT to satisfy your PT/WW cap constraints. Current PT cap is ${simulationFacts.ptLimit} relative to FT staff.`,
                    icon: <Scale className="w-5 h-5" />,
                    color: "bg-emerald-100 text-emerald-600"
                  }
                ].map((step, i) => (
                  <div key={i} className="flex gap-4 p-5 bg-white border border-slate-200 rounded-xl group transition-all">
                    <div className="flex-shrink-0">
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center ${step.color}`}>
                        {step.icon}
                      </div>
                    </div>
                    <div>
                      <h4 className="font-bold text-slate-800 flex items-center gap-2">
                        Step {i + 1}: {step.title}
                        <ChevronRight className="w-4 h-4 text-slate-300 group-hover:translate-x-1 transition-transform" />
                      </h4>
                      <p className="text-slate-600 text-sm mt-1 leading-relaxed">
                        {step.desc}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <div className="bg-indigo-900 text-white p-6 rounded-xl border border-indigo-700 shadow-xl">
                <h3 className="font-bold mb-4 flex items-center gap-2 text-sm uppercase tracking-wider opacity-90">
                  <Lightbulb className="w-5 h-5 text-yellow-400" />
                  Key Features
                </h3>
                <div className="space-y-4">
                  <div className="border-b border-white/10 pb-3">
                    <p className="text-[10px] uppercase opacity-60 font-bold mb-1">Morning Handover</p>
                    <p className="text-sm">Morning shifts end at 15:00. Afternoon shifts start at 15:00. Zero overlap wastage.</p>
                  </div>
                  <div className="border-b border-white/10 pb-3">
                    <p className="text-[10px] uppercase opacity-60 font-bold mb-1">Night Logic</p>
                    <p className="text-sm">Night shift moved from 22:00 to 23:00, ending at 08:00.</p>
                  </div>
                  <div>
                    <p className="text-[10px] uppercase opacity-60 font-bold mb-1">Utilization</p>
                    <p className="text-sm">Blended efficiency is {solution.weeklyStats.blendedUtilization.toFixed(1)}%.</p>
                  </div>
                </div>
              </div>

              <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                  <Target className="w-5 h-5 text-indigo-600" />
                  Target Peak
                </h3>
                <p className="text-xs text-slate-600 leading-relaxed font-medium">
                  The model prioritized staffing for <strong>{simulationFacts.maxDay} ({simulationFacts.maxBlock})</strong> which required {simulationFacts.requiredHeadsAtPeak} concurrent heads.
                </p>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SolutionDashboard;

export type TimeBlock = 
  | '06:00-10:00' 
  | '10:00-14:00' 
  | '14:00-18:00' 
  | '18:00-22:00' 
  | '22:00-02:00' 
  | '02:00-06:00';

export type DayOfWeek = 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat' | 'Sun';
export type RoleType = 'Full Time' | 'Part Time' | 'Weekend Warrior';

export interface DemandData {
  day: DayOfWeek;
  blocks: Record<TimeBlock, number>;
}

export interface Constraints {
  avgProductivity: number; 
  targetUtilization: number; 
  minWeeklyOffs: number; 
  weekendSpike: number; 
  partTimeCap: number; 
  weekendCap: number; 
}

export interface AssociateRoster {
  id: string;
  name: string;
  role: RoleType;
  schedule: Record<DayOfWeek, string>; 
  totalHours: number;
}

export interface StaffingSolution {
  /**
   * Fixed: Updated to allow 'ortools' and 'ai' methods to support the different solvers in the codebase.
   */
  solverMethod?: 'greedy' | 'ortools' | 'ai';
  strategySummary: string;
  weeklyStats: {
    totalVolume: number;
    totalHeadcount: number;
    blendedUtilization: number;
    mix: {
      ft: number;
      pt: number;
      weekend: number;
    };
  };
  roster: AssociateRoster[];
  recommendations: string[];
}

const createEmptyDay = (day: DayOfWeek): DemandData => ({
  day,
  blocks: {
    '06:00-10:00': 0,
    '10:00-14:00': 0,
