/**
 * Senior Frontend Engineer implementation of Gemini AI Staffing Solver.
 * Adheres to @google/genai guidelines using gemini-3-pro-preview.
 */
import { GoogleGenAI, Type } from "@google/genai";
import { Constraints, DemandData, StaffingSolution } from "../types";

export const generateStaffingPlan = async (
  demand: DemandData[],
  constraints: Constraints
): Promise<StaffingSolution> => {
  // Use the API key exclusively from the environment
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Act as a workforce management consultant. Generate an optimal 24/7 staffing roster.

Demand (Orders per 4-hour block):
${JSON.stringify(demand)}

Operational Constraints:
- Avg Productivity: ${constraints.avgProductivity} orders/hour
- Target Utilization: ${constraints.targetUtilization}%
- Part-Time Cap: ${constraints.partTimeCap}% relative to Full-Time staff
- Weekend Warrior Cap: ${constraints.weekendCap}% relative to Full-Time staff

Strict Scheduling Rules:
1. Full Time (FT): 9h shift (8h productive work + 1h unpaid break). Works 6 days a week.
2. Part Time (PT): 4h shift. Works 6 days a week.
3. Weekend Warrior (WW): 9h shift (8h productive) on Saturday and Sunday ONLY.
4. The roster must ensure 100% coverage of demand in every 4-hour block.
5. Provide a detailed summary and actionable recommendations.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: "You are an expert operations research scientist. Respond only with a valid JSON object matching the requested StaffingSolution schema.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          strategySummary: { type: Type.STRING },
          weeklyStats: {
            type: Type.OBJECT,
            properties: {
              totalVolume: { type: Type.NUMBER },
              totalHeadcount: { type: Type.NUMBER },
              blendedUtilization: { type: Type.NUMBER },
              mix: {
                type: Type.OBJECT,
                properties: {
                  ft: { type: Type.NUMBER },
                  pt: { type: Type.NUMBER },
                  weekend: { type: Type.NUMBER }
                },
                required: ["ft", "pt", "weekend"]
              }
            },
            required: ["totalVolume", "totalHeadcount", "blendedUtilization", "mix"]
          },
          roster: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                role: { type: Type.STRING },
                schedule: {
                  type: Type.OBJECT,
                  properties: {
                    Mon: { type: Type.STRING },
                    Tue: { type: Type.STRING },
                    Wed: { type: Type.STRING },
                    Thu: { type: Type.STRING },
                    Fri: { type: Type.STRING },
                    Sat: { type: Type.STRING },
                    Sun: { type: Type.STRING }
                  },
                  required: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
                },
                totalHours: { type: Type.NUMBER }
              },
              required: ["id", "name", "role", "schedule", "totalHours"]
            }
          },
          recommendations: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["strategySummary", "weeklyStats", "roster", "recommendations"]
      }
    }
  });

  const text = response.text;
  if (!text) {
    throw new Error("AI model failed to generate a response text.");
  }

  const solution = JSON.parse(text) as StaffingSolution;
  solution.solverMethod = 'ai';
  return solution;
};

import React, { useState } from 'react';
import { INITIAL_CONSTRAINTS, INITIAL_DEMAND, Constraints, DemandData, StaffingSolution } from './types';
import DemandInput from './components/DemandInput';
import ConstraintsForm from './components/ConstraintsForm';
import SolutionDashboard from './components/SolutionDashboard';
import { generateAlgorithmicStaffingPlan } from './services/staffingAlgorithm';
import { generateORToolsStaffingPlan } from './services/orToolsSolver';
import { generateStaffingPlan } from './services/geminiService';
import { Layers, Zap, Loader2, BrainCircuit } from 'lucide-react';

export default function App() {
  const [activeTab, setActiveTab] = useState<'input' | 'results'>('input');
  const [demand, setDemand] = useState<DemandData[]>(INITIAL_DEMAND);
  const [constraints, setConstraints] = useState<Constraints>(INITIAL_CONSTRAINTS);
  const [isLoading, setIsLoading] = useState(false);
  const [solution, setSolution] = useState<StaffingSolution | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [solverType, setSolverType] = useState<'greedy' | 'ortools' | 'ai'>('greedy');

  /**
   * Fixed: Updated to support multiple solver backends including AI and OR-Tools logic.
   */
  const handleOptimize = async () => {
    setIsLoading(true);
    setError(null);
    setSolution(null);

    try {
      let result: StaffingSolution;

      if (solverType === 'greedy') {
        // Mock delay for UI feedback
        await new Promise(resolve => setTimeout(resolve, 800));
        result = generateAlgorithmicStaffingPlan(demand, constraints);
        result.solverMethod = 'greedy';
      } else if (solverType === 'ortools') {
        // Mock delay for UI feedback
        await new Promise(resolve => setTimeout(resolve, 800));
        result = generateORToolsStaffingPlan(demand, constraints);
      } else {
        // AI solver is asynchronous by design
        result = await generateStaffingPlan(demand, constraints);
      }

      setSolution(result);
      setActiveTab('results');
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred during optimization.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-600 rounded-lg">
              <Layers className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight">StaffOptima</h1>
          </div>
          <nav className="flex items-center gap-1 bg-slate-100 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('input')}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${
                activeTab === 'input' 
                  ? 'bg-white text-indigo-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Model Inputs
            </button>
            <button
              onClick={() => solution && setActiveTab('results')}
              disabled={!solution}
              className={`px-4 py-1.5 rounded-md text-sm font-medium transition-all ${
                activeTab === 'results' 
                  ? 'bg-white text-indigo-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700 disabled:opacity-50'
              }`}
            >
              Results
            </button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
            <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-2">
