                  </h3>
                  <div className="flex flex-col gap-3">
                    <div className="flex bg-slate-700/50 p-1 rounded-lg w-fit">
                      {(['greedy', 'ortools', 'ai'] as const).map((s) => (
                        <button
                          key={s}
                          onClick={() => setSolverType(s)}
                          className={`px-3 py-1 rounded-md text-[10px] font-bold tracking-wider uppercase transition-all ${
                            solverType === s 
                              ? 'bg-indigo-600 text-white' 
                              : 'text-slate-400 hover:text-slate-200'
                          }`}
                        >
                          {s}
                        </button>
                      ))}
                    </div>
                    <p className="text-slate-400 text-xs italic">
                       {solverType === 'greedy' && "Overlap-Free Greedy: Prioritizes seamless shift handovers."}
                       {solverType === 'ortools' && "Adaptive Solver: Balances strict coverage with structural waste logic."}
